-- Guarded promotion of the existing 319 reviewed corpus decisions.
-- Abort if any original claim or source has changed since the restored baseline.
BEGIN;
DO $$ BEGIN IF (SELECT md5(string_agg(id::text||E'\t'||claim_text||E'\t'||review_status||E'\t'||coalesce(approval_origin,''),E'\n' order by id)) FROM public.claims) <> '6219d9dd8f2d625b7961384ddbb48c90' OR (SELECT md5(string_agg(id::text||E'\t'||title||E'\t'||coalesce(url,'')||E'\t'||source_status,E'\n' order by id)) FROM public.sources) <> '151e171f4e2c72e8e6e7c0ca3355d31a' THEN RAISE EXCEPTION 'production corpus baseline changed'; END IF; END $$;

-- Reviewed stage: dcf-current-reviewed-application.sql


CREATE SCHEMA IF NOT EXISTS corpus_verification_audit;
CREATE TABLE IF NOT EXISTS corpus_verification_audit.original_claims AS SELECT * FROM public.claims;
CREATE TABLE IF NOT EXISTS corpus_verification_audit.original_claim_epistemics AS SELECT * FROM public.claim_epistemics;
CREATE TABLE IF NOT EXISTS corpus_verification_audit.original_claim_sources AS SELECT * FROM public.claim_sources;
CREATE TABLE IF NOT EXISTS corpus_verification_audit.original_claim_chunks AS SELECT * FROM public.claim_chunks;
CREATE TABLE IF NOT EXISTS corpus_verification_audit.original_sources AS SELECT * FROM public.sources;
CREATE TABLE IF NOT EXISTS corpus_verification_audit.decisions (claim_id uuid PRIMARY KEY, decision text NOT NULL, evidence_record jsonb NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());
DO $$ BEGIN IF (SELECT count(*) FROM corpus_verification_audit.original_claims) <> 1585 THEN RAISE EXCEPTION 'baseline mismatch'; END IF; END $$;
ALTER TABLE public.claims DROP CONSTRAINT IF EXISTS claims_approval_origin_check;
ALTER TABLE public.claims ADD CONSTRAINT claims_approval_origin_check CHECK (approval_origin IN ('human_manual','mentor_review','system_test_bulk','imported_existing','ai_candidate','automated_evidence_verification','corpus_evidence_review'));
UPDATE public.claims SET review_status='needs_review', approved_at=NULL, approved_by_label=NULL WHERE review_status <> 'rejected';
INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('180328bf-d785-4a6e-9287-9b20d04411ff'::uuid,'APPROVE','{"claim_id":"180328bf-d785-4a6e-9287-9b20d04411ff","personality_id":"96abdf31-9bb6-4fa9-8e02-1508cdcba4c9","personality":"A. P. J. Abdul Kalam","original_claim_text":"Kalam recalled missing selection as an Air Force pilot and moving into technical work in aerospace and defence instead.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["bfe4fc55-cb3b-4d50-848d-50baf547fd95"],"original_passage_ids":["edef2896-c95d-4a43-bdb6-54796a175a64"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Kalam recalled missing selection as an Air Force pilot and moving into technical work in aerospace and defence instead.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"bfe4fc55-cb3b-4d50-848d-50baf547fd95","url":"https://presidentofindia.nic.in/dr-apj-abdul-kalam/speeches/questionnaire-foreign-journalist","locator":"lines 34–43","source_authority":"A. P. J. Abdul Kalam, 2003 interview answers hosted by President of India, first-person primary testimony, inspected 2026-10-19","independence_assessment":"One directly inspected work; supporting contemporary or scholarly corroboration is identified in the rationale where checked. Repetition of the same underlying account is not counted as independent evidence.","original_source_inspected":true}],"verification_rationale":"Kalam directly recounts not entering the Air Force as a pilot and beginning technical work in the cited answer.","original_source_inspected":true,"material_limitation":"Self-report; the exact selection process is not independently reconstructed.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
