INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('1c773840-34a3-435e-8e8d-f51227baa7a5'::uuid,'REVISE AND APPROVE','{"claim_id":"1c773840-34a3-435e-8e8d-f51227baa7a5","personality_id":"96abdf31-9bb6-4fa9-8e02-1508cdcba4c9","personality":"A. P. J. Abdul Kalam","original_claim_text":"The first experimental SLV-3 flight in August 1979 was only partially successful; the programme reached orbit on its next attempt in July 1980.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"],"original_passage_ids":["7ad920fe-d6e8-4411-a9fc-1d0ffafb5c9e"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The first experimental SLV-3 flight in August 1979 was only partially successful; the next launch, on July 18, 1980, placed Rohini RS-1 in orbit.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"url":"https://www.isro.gov.in/SLV.html","locator":"SLV, introductory paragraphs, lines 4–6","source_id":"b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f","source_authority":"ISRO official mission record, live page inspected in batch 001","independence_assessment":"Original issuing institution; no independent corroboration is inferred from this source alone.","original_source_inspected":true}],"verification_rationale":"ISRO''s mission history directly gives both flight outcomes and the July 18 date. Institutional original record is adequate for this narrowly scoped launch chronology. The original wording was precise enough, but the proposed wording names the satellite and date for clarity.","original_source_inspected":true,"material_limitation":"Institutional record supports its own mission, award, or designation; broader causal history requires separate corroboration.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='The first experimental SLV-3 flight in August 1979 was only partially successful; the next launch, on July 18, 1980, placed Rohini RS-1 in orbit.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='1c773840-34a3-435e-8e8d-f51227baa7a5'::uuid;
