INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('1586e287-eaa7-49fe-a262-bbf7e70a06bb'::uuid,'APPROVE','{"claim_id":"1586e287-eaa7-49fe-a262-bbf7e70a06bb","personality_id":"96abdf31-9bb6-4fa9-8e02-1508cdcba4c9","personality":"A. P. J. Abdul Kalam","original_claim_text":"Kalam publicly urged a developed India by 2020; this was a political and social goal whose realization requires separate evaluation.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["c71e72cc-db1f-462b-9bb8-c313b07b825a"],"original_passage_ids":["28e2f50d-39ab-40cc-9854-a4636dec40e5"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Kalam publicly urged a developed India by 2020; this was a political and social goal whose realization requires separate evaluation.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"c71e72cc-db1f-462b-9bb8-c313b07b825a","url":"https://presidentofindia.nic.in/dr-apj-abdul-kalam/speeches/address-nation-ramparts-red-fort-new-delhi","locator":"lines 20–26, 45–49","source_authority":"A. P. J. Abdul Kalam, official 11 May 2007 Red Fort address, inspected 2026-10-19","independence_assessment":"One directly inspected work; supporting contemporary or scholarly corroboration is identified in the rationale where checked. Repetition of the same underlying account is not counted as independent evidence.","original_source_inspected":true}],"verification_rationale":"The speech explicitly urges national development by 2020; its future-oriented wording is an aspiration, not evidence of realization.","original_source_inspected":true,"material_limitation":"Contemporary outcomes are outside the claim and require a separate assessment.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
