INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('0056e637-ab83-4d5e-906a-a4fd1a6add5a'::uuid,'REVISE AND APPROVE','{"claim_id":"0056e637-ab83-4d5e-906a-a4fd1a6add5a","personality_id":"96abdf31-9bb6-4fa9-8e02-1508cdcba4c9","personality":"A. P. J. Abdul Kalam","original_claim_text":"The July 1980 SLV-3 launch placed Rohini RS-1 in orbit and established an indigenous Indian satellite-launch capability.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"],"original_passage_ids":["242879fb-5694-4ea4-b156-57d9e182a963"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"On July 18, 1980, India''s SLV-3 placed the Rohini RS-1 satellite in orbit.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"url":"https://www.isro.gov.in/SLV.html","locator":"SLV, launch account, line 4","source_id":"b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f","source_authority":"ISRO official mission record, live page inspected in batch 001","independence_assessment":"Original issuing institution; no independent corroboration is inferred from this source alone.","original_source_inspected":true}],"verification_rationale":"ISRO directly confirms the launch date and orbital placement. The broad claim that this ''established an indigenous Indian satellite-launch capability'' is interpretive and was removed.","original_source_inspected":true,"material_limitation":"Institutional record supports its own mission, award, or designation; broader causal history requires separate corroboration.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
