INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('1c531c7b-124d-4103-9f1c-87c8f9114fcd'::uuid,'APPROVE','{"claim_id":"1c531c7b-124d-4103-9f1c-87c8f9114fcd","personality_id":"96abdf31-9bb6-4fa9-8e02-1508cdcba4c9","personality":"A. P. J. Abdul Kalam","original_claim_text":"Kalam used Dhawan''s response to SLV failure and success as a model of leaders taking responsibility for setbacks and sharing credit for success.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["bfe4fc55-cb3b-4d50-848d-50baf547fd95"],"original_passage_ids":["77082752-1f1d-43f5-9340-388851a3b453"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Kalam used Dhawan''s response to SLV failure and success as a model of leaders taking responsibility for setbacks and sharing credit for success.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"bfe4fc55-cb3b-4d50-848d-50baf547fd95","url":"https://presidentofindia.nic.in/dr-apj-abdul-kalam/speeches/questionnaire-foreign-journalist","locator":"lines 41–43","source_authority":"A. P. J. Abdul Kalam, 2003 interview answers hosted by President of India, first-person primary testimony, inspected 2026-10-19","independence_assessment":"One directly inspected work; supporting contemporary or scholarly corroboration is identified in the rationale where checked. Repetition of the same underlying account is not counted as independent evidence.","original_source_inspected":true}],"verification_rationale":"Kalam recounts Dhawan taking responsibility after SLV-III failure and giving team credit after success, then explicitly states the leadership lesson.","original_source_inspected":true,"material_limitation":"This is Kalam’s retrospective interpretation of events.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
