INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('0ad9f692-4372-4895-936d-6383d12a7a96'::uuid,'REVISE AND APPROVE','{"claim_id":"0ad9f692-4372-4895-936d-6383d12a7a96","personality_id":"96abdf31-9bb6-4fa9-8e02-1508cdcba4c9","personality":"A. P. J. Abdul Kalam","original_claim_text":"ISRO presents SLV-3 as a foundation for later ASLV, PSLV, and GSLV projects, rather than as Kalam''s achievement alone.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f"],"original_passage_ids":["9e0db2ad-6b2a-4ad4-9cde-fbcecbf949b5"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"ISRO says the successful SLV-3 project paved the way for the later ASLV, PSLV, and GSLV launch-vehicle projects.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"url":"https://www.isro.gov.in/SLV.html","locator":"SLV, final paragraph, line 7","source_id":"b1670b9f-a5fa-4b1c-84d8-4ae3cd652c5f","source_authority":"ISRO official mission record, live page inspected in batch 001","independence_assessment":"Original issuing institution; no independent corroboration is inferred from this source alone.","original_source_inspected":true}],"verification_rationale":"The agency explicitly links the SLV-3 project to the three later programmes. The comparative attribution to Kalam alone is not established by this page, so it was omitted.","original_source_inspected":true,"material_limitation":"Institutional record supports its own mission, award, or designation; broader causal history requires separate corroboration.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
