INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('0fe168d7-9b34-49b4-afcf-9cfc23b469db'::uuid,'REVISE AND APPROVE','{"claim_id":"0fe168d7-9b34-49b4-afcf-9cfc23b469db","personality_id":"96abdf31-9bb6-4fa9-8e02-1508cdcba4c9","personality":"A. P. J. Abdul Kalam","original_claim_text":"His major books include Wings of Fire, India 2020, My Journey, and Ignited Minds, linking personal history with scientific and national-development ideas.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["ffa5789c-158e-4ca3-8984-d75ace8c7ef0"],"original_passage_ids":["23b60eaa-bc09-4269-ad5d-3e1600dad735"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The President’s official profile lists Wings of Fire, India 2020, My Journey, and Ignited Minds among Kalam’s books.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":"ffa5789c-158e-4ca3-8984-d75ace8c7ef0","url":"https://presidentofindia.nic.in/dr-apj-abdul-kalam-profile","locator":"lines 21–22","source_authority":"President of India, official profile provided by the President’s Secretariat, inspected 2026-10-19","independence_assessment":"One directly inspected work; supporting contemporary or scholarly corroboration is identified in the rationale where checked. Repetition of the same underlying account is not counted as independent evidence.","original_source_inspected":true}],"verification_rationale":"The book titles are directly listed, while the original interpretive clause about linking themes is not demonstrated by this passage.","original_source_inspected":true,"material_limitation":"The profile provides a selected list, not a bibliography.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
