INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('6eedc4ab-6cff-40c8-bad8-c616cd941467'::uuid,'REVISE AND APPROVE','{"claim_id":"6eedc4ab-6cff-40c8-bad8-c616cd941467","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Chronology is genuinely contested: scholars have proposed 788–820, roughly 700–750, and other ranges; the corpus therefore uses “eighth century” with qualifications rather than a falsely exact lifespan.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["da61510f-9779-46c0-b5af-2f4aaefb9b94"],"original_passage_ids":["b2eef562-2758-4a09-8b04-32aab6927214"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Scholarly datings of Shankara differ: proposed ranges include 788–820 CE, 700–750 CE, and the late seventh to early eighth centuries.","epistemic_type":"CONTESTED","evidence_references":[{"source_id":"da61510f-9779-46c0-b5af-2f4aaefb9b94","url":"https://plato.stanford.edu/entries/shankara/","locator":"Life and Works, line 44","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"SEP enumerates the three dating proposals. The internal corpus-policy sentence was removed; none of these ranges is treated as settled.","original_source_inspected":true,"material_limitation":null,"removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
