INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('6037e150-d873-4a4b-874a-4058fbeb0645'::uuid,'REMOVE FROM ACTIVE CORPUS','{"claim_id":"6037e150-d873-4a4b-874a-4058fbeb0645","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Scholars commonly place Shankara in the eighth century CE, but his exact dates remain disputed; the familiar 788–820 dates are one traditional modern scholarly proposal, not settled biography.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["da61510f-9779-46c0-b5af-2f4aaefb9b94"],"original_passage_ids":["d2a1d8f2-e158-4335-9cf1-4b47fa1e9092"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REMOVE FROM ACTIVE CORPUS","final_proposed_wording":"Scholars commonly place Shankara in the eighth century CE, but his exact dates remain disputed; the familiar 788–820 dates are one traditional modern scholarly proposal, not settled biography.","epistemic_type":"CONTESTED","evidence_references":[{"source_id":"da61510f-9779-46c0-b5af-2f4aaefb9b94","url":"https://plato.stanford.edu/entries/shankara/","locator":"Life and Works, line 44","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"The underlying date uncertainty is supported, but this record repeats the chronology already retained in claim 6eedc4ab.","original_source_inspected":true,"material_limitation":null,"removal_reason":"duplicate or malformed record","applied_to_isolated_database":true}'::jsonb);
