INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('711cf2d2-2d4d-45ab-bc9e-86d0a77a1873'::uuid,'REMOVE FROM ACTIVE CORPUS','{"claim_id":"711cf2d2-2d4d-45ab-bc9e-86d0a77a1873","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Shankara is securely described as an influential early Advaita Vedanta philosopher, commonly placed in the eighth century, while exact dates and most biographical details remain disputed.","original_review_status":"approved","original_approval_origin":"human_manual","original_source_ids":["da61510f-9779-46c0-b5af-2f4aaefb9b94"],"original_passage_ids":["2f95eee7-d616-407b-a57d-4bf78ed684ef","d2a1d8f2-e158-4335-9cf1-4b47fa1e9092"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REMOVE FROM ACTIVE CORPUS","final_proposed_wording":"Shankara is securely described as an influential early Advaita Vedanta philosopher, commonly placed in the eighth century, while exact dates and most biographical details remain disputed.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"da61510f-9779-46c0-b5af-2f4aaefb9b94","url":"https://plato.stanford.edu/entries/shankara/","locator":"Introduction, lines 17–18; Life and Works, lines 44–46","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"The statement is supported but duplicates the retained chronology and intellectual-significance records without a distinct proposition.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commenta