INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('967e920a-f812-4d9e-a3d3-ab6420ed4ba3'::uuid,'APPROVE','{"claim_id":"967e920a-f812-4d9e-a3d3-ab6420ed4ba3","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Scholars also disagree about Shankara’s sectarian identity: Advaita tradition remembers him as Shaiva, while some scholars argue for a Vaishnava orientation.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["da61510f-9779-46c0-b5af-2f4aaefb9b94"],"original_passage_ids":["2f95eee7-d616-407b-a57d-4bf78ed684ef"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Scholars also disagree about Shankara’s sectarian identity: Advaita tradition remembers him as Shaiva, while some scholars argue for a Vaishnava orientation.","epistemic_type":"CONTESTED","evidence_references":[{"source_id":"da61510f-9779-46c0-b5af-2f4aaefb9b94","url":"https://plato.stanford.edu/entries/shankara/","locator":"Life and Works, line 45","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"SEP directly contrasts the Shaiva traditional identity with scholarly Vaishnava arguments; the claim preserves disagreement.","original_source_inspected":true,"material_limitation":null,"removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
