INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('ae4b169c-d8a3-4c15-a5a4-9bfb3a8bb416'::uuid,'APPROVE','{"claim_id":"ae4b169c-d8a3-4c15-a5a4-9bfb3a8bb416","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Shankara rejects the view that liberation comes from combining Vedic action with knowledge; knowledge of Brahman alone liberates, while disciplined action prepares the mind.","original_review_status":"approved","original_approval_origin":"human_manual","original_source_ids":["a2a0752d-ffce-4a6f-b5a9-77186913ac3e"],"original_passage_ids":["a17b1b86-76f4-403f-a11b-a20bb4f7606c"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Shankara rejects the view that liberation comes from combining Vedic action with knowledge; knowledge of Brahman alone liberates, while disciplined action prepares the mind.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"a2a0752d-ffce-4a6f-b5a9-77186913ac3e","url":"https://iep.utm.edu/advaita-vedanta/","locator":"Error, True Knowledge and Practical Teachings, lines 74–75","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"IEP directly rejects knowledge-plus-action as a joint liberating cause and assigns action the preparatory role.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commentary or an independent specialist study may refine details.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
