INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('b7ccb18f-d986-4bdc-86dc-fd81ed04e5b3'::uuid,'APPROVE','{"claim_id":"b7ccb18f-d986-4bdc-86dc-fd81ed04e5b3","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"Advaita explains the experienced world through maya and avidya; this does not simply mean that ordinary experience is nothing, but that plurality lacks independent ultimate reality apart from Brahman.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["a2a0752d-ffce-4a6f-b5a9-77186913ac3e"],"original_passage_ids":["cf9dc580-cd73-4a22-b6eb-60d645b48924"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Advaita explains the experienced world through maya and avidya; this does not simply mean that ordinary experience is nothing, but that plurality lacks independent ultimate reality apart from Brahman.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"a2a0752d-ffce-4a6f-b5a9-77186913ac3e","url":"https://iep.utm.edu/advaita-vedanta/","locator":"Introduction, lines 4–6; Brahman, Jiva section, lines 34–36","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"IEP states the world is experienced and neither wholly real nor wholly unreal, with no independent ultimate existence.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commentary or an independent specialist study may refine details.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
