INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('d8f9f1b9-e3ca-4ca7-afa9-06fc0feb1af3'::uuid,'REVISE AND APPROVE','{"claim_id":"d8f9f1b9-e3ca-4ca7-afa9-06fc0feb1af3","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"His significance lies in systematic nondual Upanishadic interpretation and a knowledge-centered path to liberation; received commentarial attributions require separate assessment.","original_review_status":"approved","original_approval_origin":"human_manual","original_source_ids":["91083ab0-e904-4bc3-bba3-a172d04d54c6","a2a0752d-ffce-4a6f-b5a9-77186913ac3e","c833b2a2-932f-4715-8339-d3f1860dc99d"],"original_passage_ids":["5ecd1ab7-405b-4f98-9299-c19f7d161698","a17b1b86-76f4-403f-a11b-a20bb4f7606c","7868b646-5dd5-498f-905f-2d5f3b3c4f3c","c7bb517f-d656-4831-9915-ba247f318b48"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Shankara systematized nondual interpretation of the Upanishads and taught liberation through knowledge; many later works attributed to him have disputed authorship.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":null,"url":"https://plato.stanford.edu/entries/shankara/","locator":"Life and Works, lines 51–56; Methods, lines 202–204","source_authority":"Scholarly encyclopedia entry by a named professional philosopher; full live entry inspected 2026-10-19","independence_assessment":"Separate scholarly work from the database excerpt; SEP and IEP are distinct editorial works, though not assumed independent when repeating shared underlying scholarship.","original_source_inspected":true}],"verification_rationale":"SEP supports both the philosophical summary and authorship caution. The revised wording specifies the disputed attributions.","original_source_inspected":true,"material_limitation":"Interpretive claims are attributed to the scholarly entry; primary commentary or an independent specialist study may refine details.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
