INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('28401dfa-7157-482a-a8be-74bca54e6111'::uuid,'APPROVE','{"claim_id":"28401dfa-7157-482a-a8be-74bca54e6111","personality_id":"32e53e02-71cd-4232-9d33-247d37f039a7","personality":"Adi Shankaracharya","original_claim_text":"A Sanskrit Documents repository preserves a text labeled Bhagavad Gita Shankara Bhashya; the repository’s attribution documents received textual tradition, while scholarly authorship assessment remains separate.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["91083ab0-e904-4bc3-bba3-a172d04d54c6"],"original_passage_ids":["5ecd1ab7-405b-4f98-9299-c19f7d161698"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"A Sanskrit Documents repository preserves a text labeled Bhagavad Gita Shankara Bhashya; the repository’s attribution documents received textual tradition, while scholarly authorship assessment remains separate.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"91083ab0-e904-4bc3-bba3-a172d04d54c6","url":"https://sanskritdocuments.org/doc_giitaa/gItAshAMkarabhAShya.pdf","locator":"PDF title; HTML companion document information, lines 9651–9670","source_authority":"Volunteer text repository; title and document metadata checked against the live PDF and companion page","independence_assessment":"Repository label is not independent evidence of eighth-century authorship.","original_source_inspected":true}],"verification_rationale":"The live Sanskrit Documents PDF and companion metadata identify a text under the Shankara-bhashya title. This verifies repository labeling, not historical authorship.","original_source_inspected":true,"material_limitation":"The volunteer transcription may not be reproduced for site promotion without permission; this claim uses metadata only.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
