INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('aa325491-b9d3-47d0-8ea9-0a4ede4e7379'::uuid,'REVISE AND APPROVE','{"claim_id":"aa325491-b9d3-47d0-8ea9-0a4ede4e7379","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"The major edicts identify their issuer primarily as King Piyadasi, “Beloved of the Gods,” a royal titulary that foregrounds authority rather than a personal biography.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d7cc7107-cdf7-4d87-9e39-06c917f472b8"],"original_passage_ids":["bf4fd006-287f-4f8f-a65a-e0fce37230b0"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The major rock edicts identify their issuer as Devanampiya Piyadasi, conventionally translated as the king ''Beloved of the Gods, Piyadasi.''","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"d7cc7107-cdf7-4d87-9e39-06c917f472b8","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=362","locator":"Major Rock Edicts, recurring royal titulary; especially II and XIII","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 250, 253 (PDF pages 1, 4)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"The edicts repeatedly use this title. The original inference about foregrounding authority is removed because the inscription does not itself establish the author''s purpose.","original_source_inspected":true,"material_limitation":"The association of Piyadasi with Ashoka is a historical identification supported by other inscriptions, not a name stated in most major rock edicts.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='The major rock edicts identify their issuer as Devanampiya Piyadasi, conventionally translated as the king ''Beloved of the Gods, Piyadasi.''',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='aa325491-b9d3-47d0-8ea9-0a4ede4e7379'::uuid;
