INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('be5e3251-a901-4d3c-956b-1d82f7ad75be'::uuid,'REVISE AND APPROVE','{"claim_id":"be5e3251-a901-4d3c-956b-1d82f7ad75be","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Minor Rock Inscription evidence explicitly uses the name Ashoka, helping connect the named king with the Piyadasi of the larger inscriptional corpus.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["ff913930-89f5-4f50-ac11-db6205f5a5b3"],"original_passage_ids":["932584fa-7b3c-477c-b089-8081f2ce57f4"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The Maski version of Minor Rock Edict I names Devanampiya Ashoka, providing inscriptional evidence that connects the Ashoka name with the royal Devanampiya titulary used elsewhere.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":"ff913930-89f5-4f50-ac11-db6205f5a5b3","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=399","locator":"Maski Minor Rock Edict I","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 259 (PDF pages 10)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"The Maski version explicitly names Ashoka; this supports the identification without claiming every Piyadasi inscription independently names him.","original_source_inspected":true,"material_limitation":"The name identification combines inscriptions from different sites.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='The Maski version of Minor Rock Edict I names Devanampiya Ashoka, providing inscriptional evidence that connects the Ashoka name with the royal Devanampiya titulary used elsewhere.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='be5e3251-a901-4d3c-956b-1d82f7ad75be'::uuid;
