INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('03029219-0bd4-4396-aa14-9cddf074e25a'::uuid,'APPROVE','{"claim_id":"03029219-0bd4-4396-aa14-9cddf074e25a","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Pillar Edict VII lists shade trees, mango groves, wells and rest houses as welfare measures, linking public works to the king’s dhamma program.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["0662151b-0d88-4b60-b631-cedc9303e5b6"],"original_passage_ids":["f6a532be-b4d6-4e14-8c2d-b8fc4e5d3fa1"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Pillar Edict VII lists shade trees, mango groves, wells and rest houses as welfare measures, linking public works to the king’s dhamma program.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"0662151b-0d88-4b60-b631-cedc9303e5b6","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=370","locator":"Pillar Edict VII, public works paragraph","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 258 (PDF pages 9)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"Pillar VII lists shade trees, mango groves, wells, and rest houses in its catalogue of works for people and animals.","original_source_inspected":true,"material_limitation":"A royal list of works is not independent proof that each work was completed everywhere claimed.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Pillar Edict VII lists shade trees, mango groves, wells and rest houses as welfare measures, linking public works to the king’s dhamma program.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='03029219-0bd4-4396-aa14-9cddf074e25a'::uuid;
