INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('1e12002c-eeee-4f7d-b26c-648f36aa5a16'::uuid,'REVISE AND APPROVE','{"claim_id":"1e12002c-eeee-4f7d-b26c-648f36aa5a16","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Pillar Edict III orders periodic official tours for dhamma instruction and other business, joining communication, inspection and administration.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["0662151b-0d88-4b60-b631-cedc9303e5b6"],"original_passage_ids":["85316d18-96cb-4884-ad3d-8ed2627f3583"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Major Rock Edict III orders yuktas, rajukas and pradesikas to tour every five years for dhamma instruction and other official business.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":null,"url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=362","locator":"Major Rock Edict III, five-year circuits","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 251 (PDF pages 2)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"The cited itinerary occurs in Major Rock Edict III; the original claim misidentified it as Pillar Edict III. The relevant rock inscription was checked directly.","original_source_inspected":true,"material_limitation":"The edict records an order, not independent proof that every tour occurred.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Major Rock Edict III orders yuktas, rajukas and pradesikas to tour every five years for dhamma instruction and other official business.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='1e12002c-eeee-4f7d-b26c-648f36aa5a16'::uuid;
