INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('484c2601-2461-42e9-9899-d9b927065189'::uuid,'APPROVE','{"claim_id":"484c2601-2461-42e9-9899-d9b927065189","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Major Rock Edict VI represents the king as seeking constant reports on people’s affairs, an inscriptional ideal of accessible, informed kingship.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d7cc7107-cdf7-4d87-9e39-06c917f472b8"],"original_passage_ids":["da22d05a-c2af-4a81-94cd-1f5d887b0a91"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Major Rock Edict VI represents the king as seeking constant reports on people’s affairs, an inscriptional ideal of accessible, informed kingship.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"d7cc7107-cdf7-4d87-9e39-06c917f472b8","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=362","locator":"Major Rock Edict VI, reports and audiences","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 251 (PDF pages 2)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"Rock Edict VI says reports may reach the king at any time and in several settings; this supports the stated inscriptional ideal.","original_source_inspected":true,"material_limitation":"The edict cannot establish how accessible the king was in practice.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Major Rock Edict VI represents the king as seeking constant reports on people’s affairs, an inscriptional ideal of accessible, informed kingship.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='484c2601-2461-42e9-9899-d9b927065189'::uuid;
