INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('6587fef5-f0f9-404d-a641-960ab1cc493c'::uuid,'APPROVE','{"claim_id":"6587fef5-f0f9-404d-a641-960ab1cc493c","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Major Rock Edict XIV explains that multiple edicts were written in varied forms, direct evidence that inscriptions were a deliberate program of imperial communication.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d7cc7107-cdf7-4d87-9e39-06c917f472b8"],"original_passage_ids":["d030acfb-e1db-4dea-9561-258fa90d5d61"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Major Rock Edict XIV explains that multiple edicts were written in varied forms, direct evidence that inscriptions were a deliberate program of imperial communication.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"d7cc7107-cdf7-4d87-9e39-06c917f472b8","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=362","locator":"Major Rock Edict XIV, short, medium, and expanded versions","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 254 (PDF pages 5)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"Rock Edict XIV explicitly describes differently sized inscriptions, repetition, and geographic variation.","original_source_inspected":true,"material_limitation":"Purpose is inferred from the king''s own explanation, not from a surviving administrative plan.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
