INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('c00f9223-9075-4d15-afab-4f7771f185c3'::uuid,'REVISE AND APPROVE','{"claim_id":"c00f9223-9075-4d15-afab-4f7771f185c3","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"The Separate Rock Edicts order urban officials to instruct people in dhamma and make regular tours, showing how moral policy was tied to administrative personnel.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["052250de-cf26-4d76-80a7-786721c7638d"],"original_passage_ids":["37b730f4-58df-437f-93f0-3ff673fa0f1f"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Separate Kalinga Edict I instructs urban magistrates and provides for periodic inspection tours, linking the king''s welfare language to named officials.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"052250de-cf26-4d76-80a7-786721c7638d","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=364","locator":"Separate Kalinga Edict I, urban officials and five-year inspectors","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 255 (PDF pages 6)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"The source explicitly addresses town magistrates and says appointed officers would tour periodically. ''Dhamma instruction'' in the original compressed distinct passages and was narrowed.","original_source_inspected":true,"material_limitation":"The order is a royal claim, not proof of uniform enforcement.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
