INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('cc9a5d34-1583-4ccc-9289-4f6204ee8b45'::uuid,'APPROVE','{"claim_id":"cc9a5d34-1583-4ccc-9289-4f6204ee8b45","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Pillar Edict IV states a desire for uniform judicial procedure and punishment, revealing a claim to more regular imperial justice.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["0662151b-0d88-4b60-b631-cedc9303e5b6"],"original_passage_ids":["b8cd4dd9-8974-4841-b0f2-1aa56eb8df28"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Pillar Edict IV states a desire for uniform judicial procedure and punishment, revealing a claim to more regular imperial justice.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"0662151b-0d88-4b60-b631-cedc9303e5b6","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=370","locator":"Pillar Edict IV, judicial uniformity","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 257 (PDF pages 8)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"Pillar IV calls for uniformity in