INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('e22a25ca-a4dd-432f-ad3f-0346ebae6593'::uuid,'APPROVE','{"claim_id":"e22a25ca-a4dd-432f-ad3f-0346ebae6593","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Pillar Edict VII says that Ashoka appointed dhamma officers concerned with the welfare of different groups; it is direct evidence for a named official function, though its practical reach is debated.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["0662151b-0d88-4b60-b631-cedc9303e5b6"],"original_passage_ids":["f0575114-f607-4d60-9afd-814aa182fbc4"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Pillar Edict VII says that Ashoka appointed dhamma officers concerned with the welfare of different groups; it is direct evidence for a named official function, though its practical reach is debated.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"0662151b-0d88-4b60-b631-cedc9303e5b6","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=370","locator":"Pillar Edict VII, dhamma officers and sects","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 257–258 (PDF pages 8, 9)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"Pillar VII names dhamma officers and their work with religious groups and public welfare.","original_source_inspected":true,"material_limitation":"The edict''s appointment claim is direct; the scope of actual activity remains uncertain.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
