INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('f560127d-4eb6-42c7-bf5c-600417870b9b'::uuid,'APPROVE','{"claim_id":"f560127d-4eb6-42c7-bf5c-600417870b9b","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Major Rock Edict II declares provision for medical treatment for people and animals within Ashoka’s dominions and among borderers.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d7cc7107-cdf7-4d87-9e39-06c917f472b8"],"original_passage_ids":["d1fcfca8-6950-4f0e-b013-d3b37cbcc9b0"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Major Rock Edict II declares provision for medical treatment for people and animals within Ashoka’s dominions and among borderers.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"d7cc7107-cdf7-4d87-9e39-06c917f472b8","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=362","locator":"Major Rock Edict II, medical provision","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 250 (PDF pages 1)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"Rock II declares two kinds of medical treatment, for humans and animals, in the dominions and named neighboring regions.","original_source_inspected":true,"material_limitation":"The edict is a declaration; medical provision in foreign polities is not independently established.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
