INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('1cdd2257-0e78-4f1f-a14f-044f5661a387'::uuid,'REVISE AND APPROVE','{"claim_id":"1cdd2257-0e78-4f1f-a14f-044f5661a387","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"The edicts name Cholas, Pandyas and other southern neighbors, placing Mauryan power alongside—not simply over—all political communities of the subcontinent.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d7cc7107-cdf7-4d87-9e39-06c917f472b8"],"original_passage_ids":["d1fcfca8-6950-4f0e-b013-d3b37cbcc9b0"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Major Rock Edict II names the Cholas, Pandyas, Satyaputras, Keralaputras and Tambapanni separately from the king''s own dominions.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"d7cc7107-cdf7-4d87-9e39-06c917f472b8","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=362","locator":"Major Rock Edict II, southern polities","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 250 (PDF pages 1)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"The text explicitly distinguishes dominions from border regions. The broader conclusion about all political communities of the subcontinent was removed.","original_source_inspected":true,"material_limitation":"Its list is not a complete map of Mauryan sovereignty.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
