INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('699f3619-930c-4de3-8424-794d7e38594c'::uuid,'APPROVE','{"claim_id":"699f3619-930c-4de3-8424-794d7e38594c","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"The Separate Kalinga Edicts use paternal language—“All men are my children”—to frame royal concern and the obligations of officials.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["052250de-cf26-4d76-80a7-786721c7638d"],"original_passage_ids":["314e063d-9ce8-4b3c-9cde-d39620203a5f"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The Separate Kalinga Edicts use paternal language—“All men are my children”—to frame royal concern and the obligations of officials.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"052250de-cf26-4d76-80a7-786721c7638d","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=364","locator":"Separate Kalinga Edict I, children and officials","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 255 (PDF pages 6)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"The edict says ''All men are my children'' in an address to officials about welfare and justice.","original_source_inspected":true,"material_limitation":"Paternal language should not be taken as proof of subjects'' experience.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
