INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('ef6898e4-5bfa-489b-b7d4-5ee29481470c'::uuid,'APPROVE','{"claim_id":"ef6898e4-5bfa-489b-b7d4-5ee29481470c","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"In Major Rock Edict XIII, Ashoka states remorse after Kalinga, especially over suffering caused to Brahmanas, ascetics and households.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d7cc7107-cdf7-4d87-9e39-06c917f472b8"],"original_passage_ids":["120a4baa-09a6-4e99-b9a9-611b87665172"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"In Major Rock Edict XIII, Ashoka states remorse after Kalinga, especially over suffering caused to Brahmanas, ascetics and households.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"d7cc7107-cdf7-4d87-9e39-06c917f472b8","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=362","locator":"Major Rock Edict XIII, remorse and religious households","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 253–254 (PDF pages 4, 5)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"Rock XIII explicitly expresses remorse and enumerates Brahmanas, ascetics, householders, and harm to kin.","original_source_inspected":true,"material_limitation":"Remorse is the king''s stated perspective, not an independently testable inner state.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
