INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('1c6ca1ef-95b8-4efb-a1c5-79ec2a456f58'::uuid,'APPROVE','{"claim_id":"1c6ca1ef-95b8-4efb-a1c5-79ec2a456f58","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Major Rock Edict XIII says that Ashoka conquered Kalinga in his eighth regnal year, making the campaign an unusually direct subject of contemporary royal testimony.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d7cc7107-cdf7-4d87-9e39-06c917f472b8"],"original_passage_ids":["bf4fd006-287f-4f8f-a65a-e0fce37230b0"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Major Rock Edict XIII says that Ashoka conquered Kalinga in his eighth regnal year, making the campaign an unusually direct subject of contemporary royal testimony.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"d7cc7107-cdf7-4d87-9e39-06c917f472b8","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=362","locator":"Major Rock Edict XIII, opening Kalinga sentence","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 253 (PDF pages 4)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"Rock XIII places the conquest in the eighth year after consecration.","original_source_inspected":true,"material_limitation":"The calendar year depends on reconstructing the accession chronology.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
