INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('72d5cc0b-06da-4e67-bceb-84e02791294e'::uuid,'REVISE AND APPROVE','{"claim_id":"72d5cc0b-06da-4e67-bceb-84e02791294e","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"The Kalinga edict’s acknowledgement that many more died than those reported killed or deported makes it an exceptional royal statement of war’s human cost for the third century BCE.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d7cc7107-cdf7-4d87-9e39-06c917f472b8"],"original_passage_ids":["4ca69df5-38c0-4f29-8f4e-d8f855e23f6f"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Major Rock Edict XIII says that 150,000 people were deported, 100,000 killed, and many times that number died in the conquest of Kalinga.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"d7cc7107-cdf7-4d87-9e39-06c917f472b8","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=362","locator":"Major Rock Edict XIII, reported casualties","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 253 (PDF pages 4)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"The casualty categories and numbers are explicit; the original comparative claim that the statement was ''exceptional'' requires broader historical comparison and was removed.","original_source_inspected":true,"material_limitation":"Royal casualty numbers are not independently audited.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Major Rock Edict XIII says that 150,000 people were deported, 100,000 killed, and many times that number died in the conquest of Kalinga.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='72d5cc0b-06da-4e67-bceb-84e02791294e'::uuid;
