INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('0a07ea19-5303-42b1-b028-c6a06788953c'::uuid,'APPROVE','{"claim_id":"0a07ea19-5303-42b1-b028-c6a06788953c","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Major Rock Edict II frames welfare measures as extending to borderlands and names a Greek king Antiochus, showing that Ashoka’s public horizon included neighboring polities.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d7cc7107-cdf7-4d87-9e39-06c917f472b8"],"original_passage_ids":["d1fcfca8-6950-4f0e-b013-d3b37cbcc9b0"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Major Rock Edict II frames welfare measures as extending to borderlands and names a Greek king Antiochus, showing that Ashoka’s public horizon included neighboring polities.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"d7cc7107-cdf7-4d87-9e39-06c917f472b8","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=362","locator":"Major Rock Edict II, Antiochus and neighboring polities","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 250 (PDF pages 1)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"Rock II names Antiochus and several neighbors while proclaiming human and animal medical measures.","original_source_inspected":true,"material_limitation":"Reference to a king abroad establishes the claimed geographic horizon, not confirmed delivery of medical services there.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
