INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('145b3ed1-dd94-403b-a3e5-dc7a51e5c05d'::uuid,'APPROVE','{"claim_id":"145b3ed1-dd94-403b-a3e5-dc7a51e5c05d","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Major Rock Edict XIII names Antiochus and other Hellenistic rulers in its account of dhamma victory; the wording is evidence of claimed diplomatic reach, not proof that foreign rulers adopted Ashoka’s policy.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d7cc7107-cdf7-4d87-9e39-06c917f472b8"],"original_passage_ids":["1e29da7c-8ac3-435d-a4f4-e79bf61f48e6"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Major Rock Edict XIII names Antiochus and other Hellenistic rulers in its account of dhamma victory; the wording is evidence of claimed diplomatic reach, not proof that foreign rulers adopted Ashoka’s policy.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"d7cc7107-cdf7-4d87-9e39-06c917f472b8","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=362","locator":"Major Rock Edict XIII, Hellenistic rulers","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 254 (PDF pages 5)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"Rock XIII names Antiochus and other Greek rulers within its dhamma-victory rhetoric; the claim properly avoids asserting their compliance.","original_source_inspected":true,"material_limitation":"Named rulers help chronological interpretation but do not independently prove diplomatic missions.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
