INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('12073932-efe6-4337-b8e4-43ce16eb6257'::uuid,'APPROVE','{"claim_id":"12073932-efe6-4337-b8e4-43ce16eb6257","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Major Rock Edict XII warns against praising one’s own sect while condemning others without reason, making inter-sectarian restraint an explicit imperial norm.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d7cc7107-cdf7-4d87-9e39-06c917f472b8"],"original_passage_ids":["346cb83b-c782-4216-a42c-77bd1b396e03"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Major Rock Edict XII warns against praising one’s own sect while condemning others without reason, making inter-sectarian restraint an explicit imperial norm.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"d7cc7107-cdf7-4d87-9e39-06c917f472b8","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=362","locator":"Major Rock Edict XII, sectarian speech","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 253 (PDF pages 4)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"Rock XII cautions against glorifying one''s sect by disparaging another without cause.","original_source_inspected":true,"material_limitation":"This is an imperial prescription, not evidence of universal religious tolerance in practice.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Major Rock Edict XII warns against praising one’s own sect while condemning others without reason, making inter-sectarian restraint an explicit imperial norm.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='12073932-efe6-4337-b8e4-43ce16eb6257'::uuid;
