INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('703d0b52-4449-4b89-8f65-4a771c952965'::uuid,'REVISE AND APPROVE','{"claim_id":"703d0b52-4449-4b89-8f65-4a771c952965","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"Minor Rock Edict I describes Ashoka as a Buddhist lay disciple and says he visited the Buddhist community, contemporary evidence for personal Buddhist affiliation.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["ff913930-89f5-4f50-ac11-db6205f5a5b3"],"original_passage_ids":["91a96e93-f753-4a92-b8c5-c120ca2f9676"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"In Minor Rock Edict I, the king describes himself as a Buddhist lay follower and says he had visited the sangha.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"ff913930-89f5-4f50-ac11-db6205f5a5b3","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=399","locator":"Minor Rock Edict I, lay devotion and sangha","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 259 (PDF pages 10)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"The Rupnath and Brahmagiri versions describe his religious status and visit. The wording is tied to the inscription rather than asserting a directly observed private belief.","original_source_inspected":true,"material_limitation":"English renderings vary between ''lay follower,'' ''upasaka,'' and ''Sakya''.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
