INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('a0e13cea-bb7e-405e-9197-68698a826df5'::uuid,'APPROVE','{"claim_id":"a0e13cea-bb7e-405e-9197-68698a826df5","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"The Bairat inscription recommends particular teachings to monks, nuns and lay followers, stronger evidence of Ashoka’s engagement with Buddhism than the general Major Edicts provide.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["ff913930-89f5-4f50-ac11-db6205f5a5b3"],"original_passage_ids":["6a414276-0c90-4f66-b347-a237ab998096"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The Bairat inscription recommends particular teachings to monks, nuns and lay followers, stronger evidence of Ashoka’s engagement with Buddhism than the general Major Edicts provide.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"ff913930-89f5-4f50-ac11-db6205f5a5b3","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=399","locator":"Bairat/Bhabru inscription, recommended teachings","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 259 (PDF pages 10)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"The Bairat text directly recommends named Buddhist teachings to monks, nuns, and lay followers.","original_source_inspected":true,"material_limitation":"Textual patronage does not by itself establish the extent of Buddhist practice across the empire.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
