INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('b1f391e8-502c-4078-80b9-69265174c8e1'::uuid,'REVISE AND APPROVE','{"claim_id":"b1f391e8-502c-4078-80b9-69265174c8e1","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"The Nigali Sagar inscription records enlargement of a stupa for the Buddha Konakamana and an imperial visit, evidence for support of particular Buddhist sacred sites.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["cf34f9b9-15ae-4be6-b9ba-34718a351904"],"original_passage_ids":["10d33019-e827-4fa6-bb11-eee858371da6"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The Nigali Sagar pillar inscription says the king enlarged the stupa of the Buddha Konakamana and later visited and worshipped at the site.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"cf34f9b9-15ae-4be6-b9ba-34718a351904","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=378","locator":"Nigali Sagar pillar inscription","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 260 (PDF pages 11)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"The inscription records these acts, but its surviving text is damaged; the original assertion of completed acts was reframed as inscriptional testimony.","original_source_inspected":true,"material_limitation":"The twentieth-year reading and erection clause are partly restored in published translations.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
