INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('e95a563f-ff64-49e9-90b7-c6fae169bdd6'::uuid,'REVISE AND APPROVE','{"claim_id":"e95a563f-ff64-49e9-90b7-c6fae169bdd6","personality_id":"f12656ee-8f17-40da-9dd6-6163e9eb20d5","personality":"Ashoka","original_claim_text":"The Lumbini pillar inscription records Ashoka’s visit and worship at the Buddha’s birthplace, combining pilgrimage, tax policy and royal commemoration.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["cf34f9b9-15ae-4be6-b9ba-34718a351904"],"original_passage_ids":["0dba1dfb-0e5e-4f65-85ea-69de02069cba"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The Lumbini pillar inscription says the king visited and worshipped at the site identified there as the Buddha''s birthplace and granted the village a reduced tax obligation.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"cf34f9b9-15ae-4be6-b9ba-34718a351904","url":"https://www2.hf.uio.no/polyglotta/index.php?page=volume&vid=378","locator":"Lumbini/Rummindei pillar inscription","source_authority":"University of Oslo Bibliotheca Polyglotta edition of Ashokan inscriptions, based on Hultzsch''s epigraphic transcription and translation","independence_assessment":"Contemporary royal inscription; primary for what the court proclaimed, not independent proof of policy outcomes","original_source_inspected":true},{"source_id":null,"url":"https://projects.mcah.columbia.edu/indianart/pdf/asoka_thapar.pdf","locator":"Romila Thapar, ''A Translation of the Edicts of Asoka,'' printed p. 260 (PDF pages 11)","source_authority":"Scholarly translation by historian Romila Thapar, hosted by Columbia University","independence_assessment":"A second scholarly translation of the same inscription, not independent confirmation of events claimed by the ruler","original_source_inspected":true}],"verification_rationale":"The royal visit, identification, and tax provision are all explicit. The wording distinguishes the inscription''s birthplace identification from independently verifying that ancient event.","original_source_inspected":true,"material_limitation":"Tax translations vary in detail; the narrow phrase ''reduced tax obligation'' is supported by both checked renderings.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='The Lumbini pillar inscription says the king visited and worshipped at the site identified there as the Buddha''s birthplace and granted the village a reduced tax obligation.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='e95a563f-ff64-49e9-90b7-c6fae169bdd6'::uuid;
