INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('f0b7218a-596c-47fa-892c-ec9804ca5731'::uuid,'APPROVE','{"claim_id":"f0b7218a-596c-47fa-892c-ec9804ca5731","personality_id":"1cad1ad4-d440-427d-bc6d-35767a2af208","personality":"Rabindranath Tagore","original_claim_text":"In Nationalism in India, Tagore argued that India’s central problem was social—how diverse communities could live together—rather than merely the transfer of state power.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["5cce5617-0320-4efd-b9cd-87b2750768c5"],"original_passage_ids":["4b37dd5e-4b09-42d2-813f-85ce38d0596b"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"In Nationalism in India, Tagore argued that India’s central problem was social—how diverse communities could live together—rather than merely the transfer of state power.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"url":"https://www.gutenberg.org/files/40766/40766-h/40766-h.htm","locator":"lines 425–433, 511–517","source_id":"5cce5617-0320-4efd-b9cd-87b2750768c5","source_authority":"Project Gutenberg edition of Tagore, Nationalism, 1917 original text; live passage inspected 2026-10-19","independence_assessment":"Single original or institutional source. No second independent source is inferred.","original_source_inspected":true}],"verification_rationale":"The India lecture explicitly gives the social problem priority over politics and discusses relations among communities.","original_source_inspected":true,"material_limitation":"Institutional accounts and first-person recollections support the attributed or narrow claim; broader historical interpretations need independent corroboration.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
