INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('af48b048-b6a9-4e9a-a59f-09ee0496a5e4'::uuid,'REVISE AND APPROVE','{"claim_id":"af48b048-b6a9-4e9a-a59f-09ee0496a5e4","personality_id":"a2cfad28-3f09-47e1-932c-149740c3e5cd","personality":"Rajaraja Chola I","original_claim_text":"The Brihadisvara complex has been protected by the Archaeological Survey of India since 1922 and is now part of the UNESCO-listed Great Living Chola Temples.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["dfea9d16-e203-4fc9-aa62-53a649dbd7b4"],"original_passage_ids":["a4ee4941-9775-4b43-8ff3-498794c82b46"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The Brihadisvara Temple at Thanjavur has been under Archaeological Survey of India protection since 1922 and is part of the UNESCO-listed Great Living Chola Temples.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"url":"https://whc.unesco.org/en/list/250/","locator":"Protection and management requirements, lines 75–76; site summary, lines 2–5","source_id":"dfea9d16-e203-4fc9-aa62-53a649dbd7b4","source_authority":"UNESCO World Heritage Centre official site entry, live page inspected in batch 001","independence_assessment":"Original issuing institution; no independent corroboration is inferred from this source alone.","original_source_inspected":true}],"verification_rationale":"UNESCO''s site record directly identifies the property and states ASI protection began in 1922. This is an institutional status claim.","original_source_inspected":true,"material_limitation":"Institutional record supports its own mission, award, or designation; broader causal history requires separate corroboration.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='The Brihadisvara Temple at Thanjavur has been under Archaeological Survey of India protection since 1922 and is part of the UNESCO-listed Great Living Chola Temples.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='af48b048-b6a9-4e9a-a59f-09ee0496a5e4'::uuid;
