INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('e4ee4929-f977-4c13-ae94-5cf2912a281f'::uuid,'REVISE AND APPROVE','{"claim_id":"e4ee4929-f977-4c13-ae94-5cf2912a281f","personality_id":"a2cfad28-3f09-47e1-932c-149740c3e5cd","personality":"Rajaraja Chola I","original_claim_text":"UNESCO’s architectural synthesis dates the Brihadisvara project to about 1003–04 through 1009–10, with the precise start phrased cautiously.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["dfea9d16-e203-4fc9-aa62-53a649dbd7b4"],"original_passage_ids":["7c7fdb01-1cf1-497f-bd52-e3a19811152f"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"UNESCO''s architectural synthesis says construction of the Brihadisvara Temple possibly began in Rajaraja I''s 19th regnal year (1003–04) and that it was consecrated in his 25th (1009–10).","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"url":"https://whc.unesco.org/en/list/250/","locator":"Outstanding Universal Value, brief synthesis, line 50","source_id":"dfea9d16-e203-4fc9-aa62-53a649dbd7b4","source_authority":"UNESCO World Heritage Centre official site entry, live page inspected in batch 001","independence_assessment":"Original issuing institution; no independent corroboration is inferred from this source alone.","original_source_inspected":true}],"verification_rationale":"The UNESCO text directly supplies both regnal-year dates and marks the inauguration as possible. Attribution to its synthesis and the uncertainty qualifier avoid overstating the historical chronology.","original_source_inspected":true,"material_limitation":"Institutional record supports its own mission, award, or designation; broader causal history requires separate corroboration.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='UNESCO''s architectural synthesis says construction of the Brihadisvara Temple possibly began in Rajaraja I''s 19th regnal year (1003–04) and that it was consecrated in his 25th (1009–10).',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='e4ee4929-f977-4c13-ae94-5cf2912a281f'::uuid;
