INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('fb1ea3bb-ab07-44df-8d1d-b586cb7ab895'::uuid,'REVISE AND APPROVE','{"claim_id":"fb1ea3bb-ab07-44df-8d1d-b586cb7ab895","personality_id":"a2cfad28-3f09-47e1-932c-149740c3e5cd","personality":"Rajaraja Chola I","original_claim_text":"The surviving Brihadisvara vimana rises about 59.82 metres and is organized in thirteen talas, material evidence of a monumental Chola architectural program.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["dfea9d16-e203-4fc9-aa62-53a649dbd7b4"],"original_passage_ids":["f2f08fa0-671b-4bb4-97f7-d66720809d71"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"UNESCO describes the Brihadisvara Temple''s vimana as 59.82 metres high with thirteen talas.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"url":"https://whc.unesco.org/en/list/250/","locator":"Outstanding Universal Value, brief synthesis, lines 51–52","source_id":"dfea9d16-e203-4fc9-aa62-53a649dbd7b4","source_authority":"UNESCO World Heritage Centre official site entry, live page inspected in batch 001","independence_assessment":"Original issuing institution; no independent corroboration is inferred from this source alone.","original_source_inspected":true}],"verification_rationale":"UNESCO directly reports the dimensions and tier count. The original interpretive phrase about material evidence of a monumental programme was removed to keep this claim tied to the documented measurement.","original_source_inspected":true,"material_limitation":"Institutional record supports its own mission, award, or designation; broader causal history requires separate corroboration.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='UNESCO describes the Brihadisvara Temple''s vimana as 59.82 metres high with thirteen talas.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='fb1ea3bb-ab07-44df-8d1d-b586cb7ab895'::uuid;
