INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('08cff6a7-0e1c-4a21-9b03-23087f2ea745'::uuid,'REVISE AND APPROVE','{"claim_id":"08cff6a7-0e1c-4a21-9b03-23087f2ea745","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"The Order''s biography claims he was \"the first religious prophet recorded in history\" to preach the harmony of religions, yet its own account says Keshab Sen was discovering the harmony of religions around the time of their first contact — a superlative best read as devotional reception, not history.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40"],"original_passage_ids":["446b4390-c17e-434f-9c08-da7f113d0ebc"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"In his introduction to The Gospel of Sri Ramakrishna, Swami Nikhilananda calls Ramakrishna the first religious prophet in recorded history to teach harmony among religions. This is the Order''s retrospective devotional assessment, not an independently established priority claim.","epistemic_type":"MODERN_RECEPTION","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/summary_of.htm","locator":"lines 3–9","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true},{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/keshab.htm","locator":"lines 3–7","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true}],"verification_rationale":"The summary directly makes the superlative claim. The adjacent Keshab chapter says Keshab''s harmony concept was deepened through contact with Ramakrishna, so the superlative cannot be adopted as an established historical ranking.","original_source_inspected":true,"material_limitation":"Order/disciples'' retrospective accounts are primary for the reported tradition and textual record, but are not independent corroboration of private events or the precision of historical dialogue.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='In his introduction to The Gospel of Sri Ramakrishna, Swami Nikhilananda calls Ramakrishna the first religious prophet in recorded history to teach harmony among religions. This is the Order''s retrospective devotional assessment, not an independently established priority claim.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='08cff6a7-0e1c-4a21-9b03-23087f2ea745'::uuid;
UPDATE public.claim_epistemics SET epistemic_type='MODERN_RECEPTION',contract_status='SUPPORTED',contract_satisfied=true,contract_basis='Source-specific corpus review; see corpus_verification_audit.decisions',reviewer_kind='ai_assisted',review_note='Evidence assessment in isolated review copy',reviewed_at=now() WHERE claim_id='08cff6a7-0e1c-4a21-9b03-23087f2ea745'::uuid;
INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('0f36dc1e-79a2-465a-981b-77b75665f4d7'::uuid,'REVISE AND APPROVE','{"claim_id":"0f36dc1e-79a2-465a-981b-77b75665f4d7","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"The Gospel''s translator, Nikhilananda, adds a note that Ramakrishna''s frequent phrase kamini-kanchan (\"woman and gold\") meant only \"lust and greed\" and that he used \"woman\" as a concrete term for the sex instinct when addressing male devotees; critics dispute such translation choices.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["6bd19767-fd30-4b73-900b-11576daedd8e","ac02dde3-2c64-4cb9-bac4-1425c20d8add"],"original_passage_ids":["25560911-71d0-4342-bc5a-f3fd8c15b58f"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"In a note to his English Gospel, translator Swami Nikhilananda explains Ramakrishna''s phrase kamini-kanchan (''woman and gold'') as ''lust and greed'' and says he used ''woman'' for the sex instinct when addressing male devotees.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/volume_1/01_master_and_disciple.htm","locator":"translator''s note 1, lines 243–246","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true}],"verification_rationale":"The original translator note directly supports the account of Nikhilananda''s explanation. The separate assertion about critics disputing it has been removed because this decision did not establish that with checked criticism.","original_source_inspected":true,"material_limitation":"Order/disciples'' retrospective accounts are primary for the reported tradition and textual record, but are not independent corroboration of private events or the precision of historical dialogue.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='In a note to his English Gospel, translator Swami Nikhilananda explains Ramakrishna''s phrase kamini-kanchan (''woman and gold'') as ''lust and greed'' and says he used ''woman'' for the sex instinct when addressing male devotees.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='0f36dc1e-79a2-465a-981b-77b75665f4d7'::uuid;
UPDATE public.claim_epistemics SET epistemic_type='TEXTUAL_ASSERTION',contract_status='SUPPORTED',contract_satisfied=true,contract_basis='Source-specific corpus review; see corpus_verification_audit.decisions',reviewer_kind='ai_assisted',review_note='Evidence assessment in isolated review copy',reviewed_at=now() WHERE claim_id='0f36dc1e-79a2-465a-981b-77b75665f4d7'::uuid;
INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('3700d177-cf5d-49c9-8c4c-00d885205139'::uuid,'APPROVE','{"claim_id":"3700d177-cf5d-49c9-8c4c-00d885205139","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"Walter Neevel (1976), building on Heinrich Zimmer, argued that Ramakrishna''s view of the ultimate is best understood as Tantric nondualism rather than Vedantic, which fits his concern with worldly activity as the Mother''s playful power.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d5a13923-a194-487e-8a9b-0d61f574d7e7"],"original_passage_ids":["cf89b2be-c8a5-4760-a26b-f995d6951532"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Walter Neevel (1976), building on Heinrich Zimmer, argued that Ramakrishna''s view of the ultimate is best understood as Tantric nondualism rather than Vedantic, which fits his concern with worldly activity as the Mother''s playful power.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"d5a13923-a194-487e-8a9b-0d61f574d7e7","url":"https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/ramakrishna","locator":"Interpretations, lines 67–70","source_authority":"Walter G. Neevel Jr. and Brian A. Hatcher, Encyclopedia of Religion entry (1987; revised 2005); first entry only, lines 29–99","independence_assessment":"Distinct scholarly and institutional works where multiple works are listed; shared tradition and possible source dependence are not counted as independent historical corroboration.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"Hatcher expressly describes Neevel’s 1976 argument building on Zimmer and its Tantric-nondual interpretation.","original_source_inspected":true,"material_limitation":"The claim attributes Neevel’s position; it does not decide the disputed classification.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Walter Neevel (1976), building on Heinrich Zimmer, argued that Ramakrishna''s view of the ultimate is best understood as Tantric nondualism rather than Vedantic, which fits his concern with worldly activity as the Mother''s playful power.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='3700d177-cf5d-49c9-8c4c-00d885205139'::uuid;
