INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('3ee6fdc4-598f-49be-97c0-d6018fe62f94'::uuid,'REVISE AND APPROVE','{"claim_id":"3ee6fdc4-598f-49be-97c0-d6018fe62f94","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"Scholars suggest Victorian-era stigma attached to Tantra made Vivekananda and the early disciples sensitive about foregrounding it, and that \"bourgeois prudery\" among devotees and Western interpreters led to aspects of his psychosexual life being denied or interpreted away.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d5a13923-a194-487e-8a9b-0d61f574d7e7"],"original_passage_ids":["89971921-cf22-4887-89cf-0ddebe479156"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Hatcher argues that late-Victorian stigma around Tantra made early disciples wary of emphasizing it, and that prudery among devotees and Western interpreters contributed to some aspects of Ramakrishna’s psychosexual life being denied or explained away.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"d5a13923-a194-487e-8a9b-0d61f574d7e7","url":"https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/ramakrishna","locator":"Interpretations, lines 74–77","source_authority":"Walter G. Neevel Jr. and Brian A. Hatcher, Encyclopedia of Religion entry (1987; revised 2005); first entry only, lines 29–99","independence_assessment":"Distinct scholarly and institutional works where multiple works are listed; shared tradition and possible source dependence are not counted as independent historical corroboration.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The passage presents a scholarly explanation and uses cautious language. The revision names Hatcher and avoids asserting historical motives as settled fact.","original_source_inspected":true,"material_limitation":"This is Hatcher’s contested interpretation of reception history, not direct evidence of each disciple’s motive.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Hatcher argues that late-Victorian stigma around Tantra made early disciples wary of emphasizing it, and that prudery among devotees and Western interpreters contributed to some aspects of Ramakrishna’s psychosexual life being denied or explained away.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='3ee6fdc4-598f-49be-97c0-d6018fe62f94'::uuid;
