INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('d8394e89-3e50-41a2-b145-70f92070b0bb'::uuid,'APPROVE','{"claim_id":"d8394e89-3e50-41a2-b145-70f92070b0bb","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"Scholars say the Ramakrishna Mission''s official position treats his experience as epitomised by Advaita Vedanta, relativising his Tantric transformation under Yogeshvari beneath Totapuri''s teaching, and they ask why Tantra is played down in the official literature.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d5a13923-a194-487e-8a9b-0d61f574d7e7"],"original_passage_ids":["3eba8c36-7648-46c9-9fa9-4437fc4da6e9"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Scholars say the Ramakrishna Mission''s official position treats his experience as epitomised by Advaita Vedanta, relativising his Tantric transformation under Yogeshvari beneath Totapuri''s teaching, and they ask why Tantra is played down in the official literature.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"d5a13923-a194-487e-8a9b-0d61f574d7e7","url":"https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/ramakrishna","locator":"Teachings/Interpretations, lines 59–60, 67–74","source_authority":"Walter G. Neevel Jr. and Brian A. Hatcher, Encyclopedia of Religion entry (1987; revised 2005); first entry only, lines 29–99","independence_assessment":"Distinct scholarly and institutional works where multiple works are listed; shared tradition and possible source dependence are not counted as independent historical corroboration.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The entry directly contrasts official Advaita primacy with Tantric interpretations and asks why Tantra was downplayed.","original_source_inspected":true,"material_limitation":"The statement reports a scholarly characterization of the Order, which the Order may contest.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Scholars say the Ramakrishna Mission''s official position treats his experience as epitomised by Advaita Vedanta, relativising his Tantric transformation under Yogeshvari beneath Totapuri''s teaching, and they ask why Tantra is played down in the official literature.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='d8394e89-3e50-41a2-b145-70f92070b0bb'::uuid;
