INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('2d6d5273-b58d-4fc2-977c-df009060e4bd'::uuid,'APPROVE','{"claim_id":"2d6d5273-b58d-4fc2-977c-df009060e4bd","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"The Order contrasts the Brahmo leader Keshab, an orator and writer who stressed social reform and treated Hindu images as allegory, with Ramakrishna, who \"hardly knew how to write his own name\", disliked lecturing and held God-realization the only goal of life.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40"],"original_passage_ids":["25972267-7868-412a-80cd-4ae4b1419c40"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The Order contrasts the Brahmo leader Keshab, an orator and writer who stressed social reform and treated Hindu images as allegory, with Ramakrishna, who \"hardly knew how to write his own name\", disliked lecturing and held God-realization the only goal of life.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/keshab.htm","locator":"lines 3–7","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true}],"verification_rationale":"Nikhilananda''s Keshab chapter explicitly makes each comparison in the claim. The wording attributes these judgments to the Order.","original_source_inspected":true,"material_limitation":"Order/disciples'' retrospective accounts are primary for the reported tradition and textual record, but are not independent corroboration of private events or the precision of historical dialogue.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='The Order contrasts the Brahmo leader Keshab, an orator and writer who stressed social reform and treated Hindu images as allegory, with Ramakrishna, who "hardly knew how to write his own name", disliked lecturing and held God-realization the only goal of life.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='2d6d5273-b58d-4fc2-977c-df009060e4bd'::uuid;
