INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('70c1dffa-4bc4-4b70-8ce1-b40d6d6c2739'::uuid,'APPROVE','{"claim_id":"70c1dffa-4bc4-4b70-8ce1-b40d6d6c2739","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"Scholars explain his appeal in colonial Calcutta: his visitors had been schooled in reason, learning and social progress, but his disdain for book-learning and for the clerk''s world, and the authenticity of his experience, made them re-examine the dignity of their spiritual heritage.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d5a13923-a194-487e-8a9b-0d61f574d7e7"],"original_passage_ids":["31a0bdc4-add5-4193-934f-88475ce33b35"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Scholars explain his appeal in colonial Calcutta: his visitors had been schooled in reason, learning and social progress, but his disdain for book-learning and for the clerk''s world, and the authenticity of his experience, made them re-examine the dignity of their spiritual heritage.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"d5a13923-a194-487e-8a9b-0d61f574d7e7","url":"https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/ramakrishna","locator":"Life, lines 49–50","source_authority":"Walter G. Neevel Jr. and Brian A. Hatcher, Encyclopedia of Religion entry (1987; revised 2005); first entry only, lines 29–99","independence_assessment":"Distinct scholarly and institutional works where multiple works are listed; shared tradition and possible source dependence are not counted as independent historical corroboration.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The entry explicitly explains the appeal to educated visitors in colonial Calcutta in these terms.","original_source_inspected":true,"material_limitation":"This is Hatcher’s historical interpretation of visitors’ responses.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Scholars explain his appeal in colonial Calcutta: his visitors had been schooled in reason, learning and social progress, but his disdain for book-learning and for the clerk''s world, and the authenticity of his experience, made them re-examine the dignity of their spiritual heritage.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='70c1dffa-4bc4-4b70-8ce1-b40d6d6c2739'::uuid;
