INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('a46df63b-dcae-4504-b6f8-337212c04b88'::uuid,'REVISE AND APPROVE','{"claim_id":"a46df63b-dcae-4504-b6f8-337212c04b88","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"Scholars call Vivekananda''s Practical Vedanta a creative transformation of Ramakrishna''s teaching, and some argue that his neo-Vedanta also reflects Western reconstructions of Advaita and Brahmo influence.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["685aedc9-c39f-4c63-a43b-2b7d4086b6ae","d5a13923-a194-487e-8a9b-0d61f574d7e7"],"original_passage_ids":["711e5f3a-deb2-4426-af20-a43c48f2f0f9"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Neevel and Hatcher describe Vivekananda’s Practical Vedanta as a creative contribution to the movement and report scholarly theories connecting it to Western morality and Western reconstructions of Vedanta.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"d5a13923-a194-487e-8a9b-0d61f574d7e7","url":"https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/ramakrishna","locator":"Life, line 53; Interpretations, lines 71–73","source_authority":"Walter G. Neevel Jr. and Brian A. Hatcher, Encyclopedia of Religion entry (1987; revised 2005); first entry only, lines 29–99","independence_assessment":"Distinct scholarly and institutional works where multiple works are listed; shared tradition and possible source dependence are not counted as independent historical corroboration.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The entry supports creative contribution and alternate Western influences. The original’s Brahmo-influence clause is not established in this passage.","original_source_inspected":true,"material_limitation":"These are reported scholarly theories, not a settled causal account.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Neevel and Hatcher describe Vivekananda’s Practical Vedanta as a creative contribution to the movement and report scholarly theories connecting it to Western morality and Western reconstructions of Vedanta.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='a46df63b-dcae-4504-b6f8-337212c04b88'::uuid;
