INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('463a43cf-ce07-4734-afd1-f82d2875592b'::uuid,'APPROVE','{"claim_id":"463a43cf-ce07-4734-afd1-f82d2875592b","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"The Order says that around November 1874 he was seized with a desire to learn the truth of Christianity and listened to the Bible read by the devotee Sambhu Charan Mallick, and then — it reports — had a vision of Christ as \"Love Incarnate\" embracing him.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40"],"original_passage_ids":["d5a354bb-40c9-4f7b-ad26-72d684d498ce"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The Order says that around November 1874 he was seized with a desire to learn the truth of Christianity and listened to the Bible read by the devotee Sambhu Charan Mallick, and then — it reports — had a vision of Christ as \"Love Incarnate\" embracing him.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/christianity.htm","locator":"lines 3–7","source_authority":"Swami Nikhilananda''s retrospective introduction to The Gospel of Sri Ramakrishna, hosted by the Ramakrishna Order; original chapter inspected 2026-10-19","independence_assessment":"Institutional devotional account; direct evidence for what the Order says, not independent corroboration of reported private or mystical events.","original_source_inspected":true}],"verification_rationale":"The chapter reports the date, Bible readings, and vision. The claim attributes the experience to the Order rather than establishing it independently.","original_source_inspected":true,"material_limitation":"Retrospective institutional account; private and mystical events cannot be independently established from this source alone.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
