INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('6d6352c0-e4ed-4414-90a4-c290e54dfa4e'::uuid,'REVISE AND APPROVE','{"claim_id":"6d6352c0-e4ed-4414-90a4-c290e54dfa4e","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"The Order says Totapuri, a wandering Advaita monk who may have been born in the Punjab, arrived at Dakshineswar toward the end of 1864; a scholarly reference entry places Ramakrishna''s instruction by him in 1864 or 1865.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40","d5a13923-a194-487e-8a9b-0d61f574d7e7"],"original_passage_ids":["5cc49b48-22f6-42d6-b589-7f790c5d3701"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Nikhilananda''s Ramakrishna Order biography dates Totapuri''s arrival at Dakshineswar to late 1864 and says he was perhaps born in Punjab.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/totapuri.htm","locator":"lines 2–3","source_authority":"Swami Nikhilananda''s retrospective introduction to The Gospel of Sri Ramakrishna, hosted by the Ramakrishna Order; original chapter inspected 2026-10-19","independence_assessment":"Institutional devotional account; direct evidence for what the Order says, not independent corroboration of reported private or mystical events.","original_source_inspected":true}],"verification_rationale":"The inspected chapter supports the Order''s account; the separate scholarly reference mentioned in the original wording was not checked for this decision, so that clause is removed.","original_source_inspected":true,"material_limitation":"Retrospective institutional account; private and mystical events cannot be independently established from this source alone.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
