INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('996d54e9-0a2c-4c3d-9d90-cdfc2501c507'::uuid,'APPROVE','{"claim_id":"996d54e9-0a2c-4c3d-9d90-cdfc2501c507","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"A scholarly reference entry summarises that he expanded his religious experience beyond Hinduism, first devoting three days to Allah and, years later, four to Christ, with visionary realisations he held to be the same as those of the Hindu divinities; these became the experiential basis for his claim that all religions can lead to the same realization.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40","d5a13923-a194-487e-8a9b-0d61f574d7e7"],"original_passage_ids":["d37b9856-2b33-4a06-823a-c6a39e744d6e"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"A scholarly reference entry summarises that he expanded his religious experience beyond Hinduism, first devoting three days to Allah and, years later, four to Christ, with visionary realisations he held to be the same as those of the Hindu divinities; these became the experiential basis for his claim that all religions can lead to the same realization.","epistemic_type":"SCHOLARLY_ATTRIBUTION","evidence_references":[{"source_id":"d5a13923-a194-487e-8a9b-0d61f574d7e7","url":"https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/ramakrishna","locator":"Life, lines 47–48","source_authority":"Walter G. Neevel Jr. and Brian A. Hatcher, Encyclopedia of Religion entry (1987; revised 2005); first entry only, lines 29–99","independence_assessment":"Distinct scholarly and institutional works where multiple works are listed; shared tradition and possible source dependence are not counted as independent historical corroboration.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The entry directly reports the three- and four-day practices, visions, and conclusion. The claim attributes the account to a scholarly reference work.","original_source_inspected":true,"material_limitation":"Specific visionary experiences remain reported experiences, not independently verifiable events.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='A scholarly reference entry summarises that he expanded his religious experience beyond Hinduism, first devoting three days to Allah and, years later, four to Christ, with visionary realisations he held to be the same as those of the Hindu divinities; these became the experiential basis for his claim that all religions can lead to the same realization.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='996d54e9-0a2c-4c3d-9d90-cdfc2501c507'::uuid;
