INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('d3d4217a-a201-414d-934a-6dab91650ba1'::uuid,'REVISE AND APPROVE','{"claim_id":"d3d4217a-a201-414d-934a-6dab91650ba1","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"In the Order''s account, a Bhairavi Brahmani, a woman adept in Tantric and Vaishnava worship who arrived at Dakshineswar around 1861, told him that his visions and ecstasies were not madness — \"you are mad for God\" — and named his state mahabhava, the exalted rapture of divine love.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40"],"original_passage_ids":["e6ac86ae-ea1f-4a64-8867-61ddc5d64fe8"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The Ramakrishna Order''s account says a Bhairavi Brahmani skilled in Tantric and Vaishnava practice reassured Ramakrishna about his visions, described his state as mahabhava, and later became his guru.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/the_brahmani.htm","locator":"lines 3–5, 20–21","source_authority":"Swami Nikhilananda''s retrospective introduction to The Gospel of Sri Ramakrishna, hosted by the Ramakrishna Order; original chapter inspected 2026-10-19","independence_assessment":"Institutional devotional account; direct evidence for what the Order says, not independent corroboration of reported private or mystical events.","original_source_inspected":true}],"verification_rationale":"The chapter directly supports the encounter and reported interpretation. An exact arrival year is not given on this page, so the date was removed.","original_source_inspected":true,"material_limitation":"Retrospective institutional account; private and mystical events cannot be independently established from this source alone.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='The Ramakrishna Order''s account says a Bhairavi Brahmani skilled in Tantric and Vaishnava practice reassured Ramakrishna about his visions, described his state as mahabhava, and later became his guru.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='d3d4217a-a201-414d-934a-6dab91650ba1'::uuid;
