INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('d4303758-2cde-468d-8a4f-bd0282b3bed3'::uuid,'APPROVE','{"claim_id":"d4303758-2cde-468d-8a4f-bd0282b3bed3","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"Scholars treat the Tantric training under the female adept Yogeshvari as formative: it helped turn his self-destructive longing into the joyful \"play\" (lila) of a child in the Mother''s \"mansion of mirth\", and gave him a framework for integrating his religious experiences.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["d5a13923-a194-487e-8a9b-0d61f574d7e7"],"original_passage_ids":["07c57b27-7011-4f2c-b9ff-9dae96222716"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Scholars treat the Tantric training under the female adept Yogeshvari as formative: it helped turn his self-destructive longing into the joyful \"play\" (lila) of a child in the Mother''s \"mansion of mirth\", and gave him a framework for integrating his religious experiences.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":"d5a13923-a194-487e-8a9b-0d61f574d7e7","url":"https://www.encyclopedia.com/people/philosophy-and-religion/hinduism-biographies/ramakrishna","locator":"Life, lines 41–44","source_authority":"Walter G. Neevel Jr. and Brian A. Hatcher, Encyclopedia of Religion entry (1987; revised 2005); first entry only, lines 29–99","independence_assessment":"Distinct scholarly and institutional works where multiple works are listed; shared tradition and possible source dependence are not counted as independent historical corroboration.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The entry describes Yogeshvari’s Tantric guidance and Hatcher’s interpretation of its effect on Ramakrishna’s theology.","original_source_inspected":true,"material_limitation":"The psychological transformation is a scholarly reading of religious biographical reports.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Scholars treat the Tantric training under the female adept Yogeshvari as formative: it helped turn his self-destructive longing into the joyful "play" (lila) of a child in the Mother''s "mansion of mirth", and gave him a framework for integrating his religious experiences.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='d4303758-2cde-468d-8a4f-bd0282b3bed3'::uuid;
