INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('1d81056a-92c0-4452-8cb1-ada016b09a58'::uuid,'APPROVE','{"claim_id":"1d81056a-92c0-4452-8cb1-ada016b09a58","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"After Ramakrishna''s death in August 1886 the young disciples gathered at a house at Baranagore rented with help from the householder Surendra, which gradually became the first monastery of the Order.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["6bd19767-fd30-4b73-900b-11576daedd8e"],"original_passage_ids":["f67d5ee6-6db7-4efc-98cd-47bc3b7ffcae"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"After Ramakrishna''s death in August 1886 the young disciples gathered at a house at Baranagore rented with help from the householder Surendra, which gradually became the first monastery of the Order.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/volume_2/52_after_the_passing_away.htm","locator":"lines 4–12","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true},{"source_id":null,"url":"https://belurmath.org/surendra-nath-mitra/","locator":"paragraph beginning ''After Sri Ramakrishna’s Maha Samadhi''","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true},{"source_id":null,"url":"https://belurmath.org/ramakrishna-math-baranagar/","locator":"opening description","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true}],"verification_rationale":"The disciple chronicle identifies the post-death Baranagore house and Surendra''s rental support; the Order''s separate Surendra and Baranagar pages directly identify it as the first monastery. These are institutionally related accounts rather than independent scholarly corroboration.","original_source_inspected":true,"material_limitation":"Order/disciples'' retrospective accounts are primary for the reported tradition and textual record, but are not independent corroboration of private events or the precision of historical dialogue.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
