INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('41d4823f-d7c5-4757-bde5-316192902188'::uuid,'APPROVE','{"claim_id":"41d4823f-d7c5-4757-bde5-316192902188","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"In M.''s record of 6 December 1884, Ramakrishna says that selfless work (karma yoga) is a way to God but very difficult and unsuited to the present age, and that helping others is the work of God alone; a man''s duty is to take refuge in God.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["6bd19767-fd30-4b73-900b-11576daedd8e"],"original_passage_ids":["a24c2255-bdf6-4389-83a2-d5bbff6fe380"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"In M.''s record of 6 December 1884, Ramakrishna says that selfless work (karma yoga) is a way to God but very difficult and unsuited to the present age, and that helping others is the work of God alone; a man''s duty is to take refuge in God.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/volume_2/34_bankim_chandra.htm","locator":"6 December 1884 entry, lines 4 and 60–70","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true}],"verification_rationale":"M.''s dated record directly states all three parts: selfless work as a path, difficulty in the present age, and the duty to seek refuge in God. This verifies what the Gospel records, not an independent verbatim transcript.","original_source_inspected":true,"material_limitation":"Order/disciples'' retrospective accounts are primary for the reported tradition and textual record, but are not independent corroboration of private events or the precision of historical dialogue.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
