INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('c387e462-e053-47bb-8ea0-b641a90acb46'::uuid,'APPROVE','{"claim_id":"c387e462-e053-47bb-8ea0-b641a90acb46","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"The Order says that at Cossipore Ramakrishna gave the ochre cloth of the sannyasi to his young disciples and Girish, and that \"the Master himself laid the foundation of the future Ramakrishna Order of monks\".","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40"],"original_passage_ids":["d9d884ea-c964-4291-8528-9751c25bf088"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The Order says that at Cossipore Ramakrishna gave the ochre cloth of the sannyasi to his young disciples and Girish, and that \"the Master himself laid the foundation of the future Ramakrishna Order of monks\".","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/last_days.htm","locator":"lines 22–23","source_authority":"Swami Nikhilananda''s retrospective introduction to The Gospel of Sri Ramakrishna, hosted by the Ramakrishna Order; original chapter inspected 2026-10-19","independence_assessment":"Institutional devotional account; direct evidence for what the Order says, not independent corroboration of reported private or mystical events.","original_source_inspected":true}],"verification_rationale":"The Order narrative directly reports the ochre cloth and interprets it as laying the monastic order''s foundation. This is an attributed institutional account.","original_source_inspected":true,"material_limitation":"Retrospective institutional account; private and mystical events cannot be independently established from this source alone.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
