INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('a4fcf4d2-e3e1-4230-bb9d-2f4770cec4b3'::uuid,'APPROVE','{"claim_id":"a4fcf4d2-e3e1-4230-bb9d-2f4770cec4b3","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"In a boat talk with Keshab Chandra Sen on 27 October 1882, Ramakrishna is recorded saying that God alone is the Teacher, that his own attitude toward God is that of a child toward its mother, and that human gurus can be had by the million but few want to be disciples.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["6bd19767-fd30-4b73-900b-11576daedd8e"],"original_passage_ids":["78abb773-19f5-49f8-b755-c8485e48b323"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"In a boat talk with Keshab Chandra Sen on 27 October 1882, Ramakrishna is recorded saying that God alone is the Teacher, that his own attitude toward God is that of a child toward its mother, and that human gurus can be had by the million but few want to be disciples.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/volume_1/05_the_master_and_keshab.htm","locator":"27 October 1882 entry, lines 4–5 and 165–169","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true}],"verification_rationale":"M.''s dated steamboat account directly records the child/mother analogy and his statement about 