INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('e33d7beb-875d-489b-958d-ac717133982f'::uuid,'REVISE AND APPROVE','{"claim_id":"e33d7beb-875d-489b-958d-ac717133982f","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"The Order''s biography says Ramakrishna married Sarada, a little girl of five from Jayrambati, in an early marriage that was in the nature of a betrothal, and that it \"remained for ever unconsummated\"; a scholarly reference entry makes the same statement.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["61914dc5-f03e-451c-81ef-145d18079b40","d5a13923-a194-487e-8a9b-0d61f574d7e7"],"original_passage_ids":["d795cec8-1729-4518-a837-46837fc98739"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Nikhilananda''s Ramakrishna Order biography says Ramakrishna married Saradamani of Jayrambati when she was five and describes their marriage as permanently unconsummated.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/introduction/marriage.htm","locator":"lines 3–5","source_authority":"Swami Nikhilananda''s retrospective introduction to The Gospel of Sri Ramakrishna, hosted by the Ramakrishna Order; original chapter inspected 2026-10-19","independence_assessment":"Institutional devotional account; direct evidence for what the Order says, not independent corroboration of reported private or mystical events.","original_source_inspected":true}],"verification_rationale":"The Order chapter supports the description. The original''s claim of scholarly corroboration was not verified for this decision and is removed; the private-life assertion remains explicitly attributed.","original_source_inspected":true,"material_limitation":"Retrospective institutional account; private and mystical events cannot be independently established from this source alone.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Nikhilananda''s Ramakrishna Order biography says Ramakrishna married Saradamani of Jayrambati when she was five and describes their marriage as permanently unconsummated.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='e33d7beb-875d-489b-958d-ac717133982f'::uuid;
