INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('0886e626-38d7-482f-bbbc-24db2fb27d60'::uuid,'APPROVE','{"claim_id":"0886e626-38d7-482f-bbbc-24db2fb27d60","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"Visiting the scholar Vidyasagar on 5 August 1882, Ramakrishna is recorded saying that the Vedas, Puranas, Tantras and philosophies have been \"defiled\" by being spoken, while Brahman alone has not, since no one can say what it is; Vidyasagar is recorded replying that he had learnt something new.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["6bd19767-fd30-4b73-900b-11576daedd8e","8cd5175c-1fa9-4fc0-9d96-2edce7212fec"],"original_passage_ids":["d9f8135e-db35-48e5-832c-bf0790227ca9"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Visiting the scholar Vidyasagar on 5 August 1882, Ramakrishna is recorded saying that the Vedas, Puranas, Tantras and philosophies have been \"defiled\" by being spoken, while Brahman alone has not, since no one can say what it is; Vidyasagar is recorded replying that he had learnt something new.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/volume_1/03_visit_to_vidyasagar.htm","locator":"5 August 1882 entry, lines 3, 33–39","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true}],"verification_rationale":"The Vidyasagar chapter supplies the date, the teaching about uttered scripture and Brahman, and Vidyasagar''s reported reaction. The wording identifies it as a recorded exchange.","original_source_inspected":true,"material_limitation":"Order/disciples'' retrospective accounts are primary for the reported tradition and textual record, but are not independent corroboration of private events or the precision of historical dialogue.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Visiting the scholar Vidyasagar on 5 August 1882, Ramakrishna is recorded saying that the Vedas, Puranas, Tantras and philosophies have been "defiled" by being spoken, while Brahman alone has not, since no one can say what it is; Vidyasagar is recorded replying that he had learnt something new.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='0886e626-38d7-482f-bbbc-24db2fb27d60'::uuid;
