INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('52dc3737-5124-467a-a553-0257baa6638e'::uuid,'REVISE AND APPROVE','{"claim_id":"52dc3737-5124-467a-a553-0257baa6638e","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"He distinguishes the jnani, who reaches Brahman by negating the world step by step, from the vijnani, who then finds that the steps are made of the same material as the roof — that Brahman has itself become the universe and living beings.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["6bd19767-fd30-4b73-900b-11576daedd8e"],"original_passage_ids":["8aac7300-70bd-46f9-9f86-bfad1ef74a18"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"In M.''s Gospel record, Ramakrishna contrasts the jnani, who reaches Brahman through ''not this, not this'', with the vijnani, who sees the steps and roof as made of the same materials and sees Brahman manifested as the universe and living beings.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/volume_1/03_visit_to_vidyasagar.htm","locator":"5 August 1882 entry, lines 55–59","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true}],"verification_rationale":"The Vidyasagar chapter directly supports the doctrinal contrast. Attribution to M.''s record was added so a theological position is not stated as an empirical fact.","original_source_inspected":true,"material_limitation":"Order/disciples'' retrospective accounts are primary for the reported tradition and textual record, but are not independent corroboration of private events or the precision of historical dialogue.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='In M.''s Gospel record, Ramakrishna contrasts the jnani, who reaches Brahman through ''not this, not this'', with the vijnani, who sees the steps and roof as made of the same materials and sees Brahman manifested as the universe and living beings.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='52dc3737-5124-467a-a553-0257baa6638e'::uuid;
