INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('9dfc87bf-82fa-41a1-b230-15ed33c2e01b'::uuid,'APPROVE','{"claim_id":"9dfc87bf-82fa-41a1-b230-15ed33c2e01b","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"Alongside his acceptance of all paths, M. records him telling a Brahmo devotee that the Eternal Religion of the rishis contains every form of worship, whereas \"the modern cults\" will last a few days and disappear — a reminder that his inclusiveness was framed within Hindu tradition.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["6bd19767-fd30-4b73-900b-11576daedd8e"],"original_passage_ids":["9d5ff842-fe76-45ce-b5bc-4caca90fad96"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Alongside his acceptance of all paths, M. records him telling a Brahmo devotee that the Eternal Religion of the rishis contains every form of worship, whereas \"the modern cults\" will last a few days and disappear — a reminder that his inclusiveness was framed within Hindu tradition.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/volume_1/20_rules.htm","locator":"entry preceding 23 March 1884, lines 74–76","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true}],"verification_rationale":"The Gospel explicitly records this statement to Bhagavan Das, identified as a Brahmo devotee. The final clause is a transparent inference from the juxtaposition, not a claim that the prediction came true.","original_source_inspected":true,"material_limitation":"Order/disciples'' retrospective accounts are primary for the reported tradition and textual record, but are not independent corroboration of private events or the precision of historical dialogue.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Alongside his acceptance of all paths, M. records him telling a Brahmo devotee that the Eternal Religion of the rishis contains every form of worship, whereas "the modern cults" will last a few days and disappear — a reminder that his inclusiveness was framed within Hindu tradition.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='9dfc87bf-82fa-41a1-b230-15ed33c2e01b'::uuid;
