INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('a22646cc-d3b9-4e43-924a-dfda00d10d24'::uuid,'APPROVE','{"claim_id":"a22646cc-d3b9-4e43-924a-dfda00d10d24","personality_id":"9ef04ec3-7bf1-4210-a951-1d6da7b2fc99","personality":"Ramakrishna Paramahamsa","original_claim_text":"Ramakrishna is recorded arguing that in the present age (Kaliyuga) people are too dependent on food and body-consciousness to say \"I am Brahman\"; those unable to give up worldly attachment should rather cherish the idea \"I am God''s servant\" and follow devotion.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["6bd19767-fd30-4b73-900b-11576daedd8e"],"original_passage_ids":["4f754e7b-7f01-471b-ae97-b4239c3002ba"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Ramakrishna is recorded arguing that in the present age (Kaliyuga) people are too dependent on food and body-consciousness to say \"I am Brahman\"; those unable to give up worldly attachment should rather cherish the idea \"I am God''s servant\" and follow devotion.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":null,"url":"https://www.ramakrishnavivekananda.info/gospel/volume_1/03_visit_to_vidyasagar.htm","locator":"5 August 1882 entry, lines 53–56","source_authority":"Swami Nikhilananda''s published Gospel translation/introduction hosted on ramakrishnavivekananda.info, or Belur Math''s institutional account; passage inspected 2026-10-19","independence_assessment":"Institutional or disciple/translator account; directly supports attributed wording or textual content, but does not independently prove private experiences or verbatim nineteenth-century speech.","original_source_inspected":true}],"verification_rationale":"The dated Vidyasagar passage directly gives the food/body-consciousness premise and recommended servant/devotee stance. The claim says ''is recorded arguing'', preserving its status as reported teaching.","original_source_inspected":true,"material_limitation":"Order/disciples'' retrospective accounts are primary for the reported tradition and textual record, but are not independent corroboration of private events or the precision of historical dialogue.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
