INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('0c4e58aa-1112-4318-8e31-c8570bb09c52'::uuid,'APPROVE','{"claim_id":"0c4e58aa-1112-4318-8e31-c8570bb09c52","personality_id":"26758dfe-ffe6-4c2c-b6c5-682353713af3","personality":"Rani Lakshmibai of Jhansi","original_claim_text":"Company intervention weakened princely rulers through residents, reduced revenues and territory, and disbanded forces; Lakshmibai’s dispute arose within this erosion of royal power.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["750f3f68-f039-49e9-a728-212d172acaaf"],"original_passage_ids":["e7856545-675e-494c-af4b-10e080d23385"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Company intervention weakened princely rulers through residents, reduced revenues and territory, and disbanded forces; Lakshmibai’s dispute arose within this erosion of royal power.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":"750f3f68-f039-49e9-a728-212d172acaaf","url":"https://ncert.nic.in/textbook/pdf/hess205.pdf","locator":"PDF p. 1, lines 10–21","source_authority":"National Council of Educational Research and Training (NCERT), Our Pasts III, ch. 5, When People Revolt: 1857 and After, 2024–25 reprint; actual PDF passage inspected 2026-10-19","independence_assessment":"One government-published secondary educational synthesis. It supports these narrowly worded, noncontroversial assertions; no independent primary record is claimed.","original_source_inspected":true}],"verification_rationale":"The NCERT text describes erosion of rulers’ authority and places Lakshmibai’s adoption dispute in that sequence.","original_source_inspected":true,"material_limitation":"Secondary textbook synthesis, not direct inspection of nineteenth-century records.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
