INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('3dbec416-e973-4e68-8e52-9f5fdfcb5ebb'::uuid,'REVISE AND APPROVE','{"claim_id":"3dbec416-e973-4e68-8e52-9f5fdfcb5ebb","personality_id":"26758dfe-ffe6-4c2c-b6c5-682353713af3","personality":"Rani Lakshmibai of Jhansi","original_claim_text":"Begum Hazrat Mahal organized resistance in Lucknow, showing that Lakshmibai was a notable woman exercising political leadership during 1857, but was not the only one.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["750f3f68-f039-49e9-a728-212d172acaaf"],"original_passage_ids":["5be41fdb-5f79-4820-b23c-8f46cbdbb4d5"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"NCERT describes Begum Hazrat Mahal as helping organise the Lucknow uprising and Lakshmibai as fighting with rebel forces in Jhansi.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":"750f3f68-f039-49e9-a728-212d172acaaf","url":"https://ncert.nic.in/textbook/pdf/hess205.pdf","locator":"PDF p. 7, lines 286–300","source_authority":"National Council of Educational Research and Training (NCERT), Our Pasts III, ch. 5, When People Revolt: 1857 and After, 2024–25 reprint; actual PDF passage inspected 2026-10-19","independence_assessment":"One government-published secondary educational synthesis. It supports these narrowly worded, noncontroversial assertions; no independent primary record is claimed.","original_source_inspected":true}],"verification_rationale":"Both women appear in the same NCERT account; the original broader judgment about political leadership is narrowed.","original_source_inspected":true,"material_limitation":"Secondary textbook synthesis, not direct inspection of nineteenth-century records.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='NCERT describes Begum Hazrat Mahal as helping organise the Lucknow uprising and Lakshmibai as fighting with rebel forces in Jhansi.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='3dbec416-e973-4e68-8e52-9f5fdfcb5ebb'::uuid;
