INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('708d3c72-9514-40a2-9159-8dc2ce0fdbbc'::uuid,'REVISE AND APPROVE','{"claim_id":"708d3c72-9514-40a2-9159-8dc2ce0fdbbc","personality_id":"26758dfe-ffe6-4c2c-b6c5-682353713af3","personality":"Rani Lakshmibai of Jhansi","original_claim_text":"Rebels invoked the Mughal emperor Bahadur Shah Zafar as a source of legitimacy, while leaders such as Lakshmibai defended local authority within the wider uprising.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["750f3f68-f039-49e9-a728-212d172acaaf"],"original_passage_ids":["1c674eb9-f122-4d5f-96d9-913751342314"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"NCERT says Meerut rebels proclaimed Bahadur Shah Zafar their leader, while Lakshmibai joined rebel sepoys in Jhansi.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":"750f3f68-f039-49e9-a728-212d172acaaf","url":"https://ncert.nic.in/textbook/pdf/hess205.pdf","locator":"PDF pp. 6–7, lines 226–237 and 297–300","source_authority":"National Council of Educational Research and Training (NCERT), Our Pasts III, ch. 5, When People Revolt: 1857 and After, 2024–25 reprint; actual PDF passage inspected 2026-10-19","independence_assessment":"One government-published secondary educational synthesis. It supports these narrowly worded, noncontroversial assertions; no independent primary record is claimed.","original_source_inspected":true}],"verification_rationale":"The source documents the two actions; the original phrase about her motive to defend local authority is an inference.","original_source_inspected":true,"material_limitation":"Secondary textbook synthesis, not direct inspection of nineteenth-century records.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='NCERT says Meerut rebels proclaimed Bahadur Shah Zafar their leader, while Lakshmibai joined rebel sepoys in Jhansi.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='708d3c72-9514-40a2-9159-8dc2ce0fdbbc'::uuid;
