INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('8c4303bd-4fa0-4c79-bad5-79840a1bcc1e'::uuid,'APPROVE','{"claim_id":"8c4303bd-4fa0-4c79-bad5-79840a1bcc1e","personality_id":"26758dfe-ffe6-4c2c-b6c5-682353713af3","personality":"Rani Lakshmibai of Jhansi","original_claim_text":"The uprising at Meerut on 10 May 1857 spread toward Delhi and other centers, turning military discontent into a much wider challenge to Company authority.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["750f3f68-f039-49e9-a728-212d172acaaf"],"original_passage_ids":["51a0e6ff-ccbe-4894-aaba-0d192e391d4b"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The uprising at Meerut on 10 May 1857 spread toward Delhi and other centers, turning military discontent into a much wider challenge to Company authority.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":"750f3f68-f039-49e9-a728-212d172acaaf","url":"https://ncert.nic.in/textbook/pdf/hess205.pdf","locator":"PDF pp. 5–7, lines 183–190 and 210–237, 272–280","source_authority":"National Council of Educational Research and Training (NCERT), Our Pasts III, ch. 5, When People Revolt: 1857 and After, 2024–25 reprint; actual PDF passage inspected 2026-10-19","independence_assessment":"One government-published secondary educational synthesis. It supports these narrowly worded, noncontroversial assertions; no independent primary record is claimed.","original_source_inspected":true}],"verification_rationale":"NCERT gives the 10 May Meerut revolt, march to Delhi, and subsequent wider uprising.","original_source_inspected":true,"material_limitation":"Secondary textbook synthesis, not direct inspection of nineteenth-century records.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
