INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('2f477182-18fd-4865-91f2-bc8f2f79c084'::uuid,'APPROVE','{"claim_id":"2f477182-18fd-4865-91f2-bc8f2f79c084","personality_id":"26758dfe-ffe6-4c2c-b6c5-682353713af3","personality":"Rani Lakshmibai of Jhansi","original_claim_text":"After the uprising, the 1858 transfer of Company power to the British Crown changed the system of imperial rule against which Lakshmibai had fought.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["750f3f68-f039-49e9-a728-212d172acaaf"],"original_passage_ids":["41ade0dd-073a-4bce-9a75-afe934aaad06"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"After the uprising, the 1858 transfer of Company power to the British Crown changed the system of imperial rule against which Lakshmibai had fought.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":"750f3f68-f039-49e9-a728-212d172acaaf","url":"https://ncert.nic.in/textbook/pdf/hess205.pdf","locator":"PDF p. 10, lines 407–429; p. 7, lines 297–300","source_authority":"National Council of Educational Research and Training (NCERT), Our Pasts III, ch. 5, When People Revolt: 1857 and After, 2024–25 reprint; actual PDF passage inspected 2026-10-19","independence_assessment":"One government-published secondary educational synthesis. It supports these narrowly worded, noncontroversial assertions; no independent primary record is claimed.","original_source_inspected":true}],"verification_rationale":"The account states that the 1858 Act transferred Company powers to the Crown; it also identifies Lakshmibai as fighting Company forces.","original_source_inspected":true,"material_limitation":"Secondary textbook synthesis, not direct inspection of nineteenth-century records.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
