INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('a440cd86-3531-45e2-adda-d77cfc4249e1'::uuid,'APPROVE','{"claim_id":"a440cd86-3531-45e2-adda-d77cfc4249e1","personality_id":"26758dfe-ffe6-4c2c-b6c5-682353713af3","personality":"Rani Lakshmibai of Jhansi","original_claim_text":"After 1857, ruling chiefs were assured that adopted heirs could succeed, but under British paramountcy; this reversed the succession policy central to Jhansi’s earlier grievance without ending colonial subordination.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["750f3f68-f039-49e9-a728-212d172acaaf"],"original_passage_ids":["7d422960-c52b-4395-9eca-5cb083734f84"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"After 1857, ruling chiefs were assured that adopted heirs could succeed, but under British paramountcy; this reversed the succession policy central to Jhansi’s earlier grievance without ending colonial subordination.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":"750f3f68-f039-49e9-a728-212d172acaaf","url":"https://ncert.nic.in/textbook/pdf/hess205.pdf","locator":"PDF pp. 1 and 11, lines 17–30 and 438–443","source_authority":"National Council of Educational Research and Training (NCERT), Our Pasts III, ch. 5, When People Revolt: 1857 and After, 2024–25 reprint; actual PDF passage inspected 2026-10-19","independence_assessment":"One government-published secondary educational synthesis. It supports these narrowly worded, noncontroversial assertions; no independent primary record is claimed.","original_source_inspected":true}],"verification_rationale":"The textbook juxtaposes refused recognition of Lakshmibai’s adopted heir with later acceptance of adopted heirs under British paramountcy.","original_source_inspected":true,"material_limitation":"Secondary textbook synthesis, not direct inspection of nineteenth-century records.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='After 1857, ruling chiefs were assured that adopted heirs could succeed, but under British paramountcy; this reversed the succession policy central to Jhansi’s earlier grievance without ending colonial subordination.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='a440cd86-3531-45e2-adda-d77cfc4249e1'::uuid;
