INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('2cc515c2-2208-42e5-8675-29a20b2629bd'::uuid,'REVISE AND APPROVE','{"claim_id":"2cc515c2-2208-42e5-8675-29a20b2629bd","personality_id":"26758dfe-ffe6-4c2c-b6c5-682353713af3","personality":"Rani Lakshmibai of Jhansi","original_claim_text":"Nana Saheb also challenged Company treatment of an adopted successor, seeking his father’s pension; his grievance helps explain the wider dynastic setting of Lakshmibai’s resistance.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["750f3f68-f039-49e9-a728-212d172acaaf"],"original_passage_ids":["22d22487-4dca-41a8-8d5b-a9e5151d6583"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"NCERT says Nana Saheb, the adopted son of Peshwa Baji Rao II, sought his father’s pension and that the Company refused; it discusses Lakshmibai’s adopted heir dispute in the same section.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":"750f3f68-f039-49e9-a728-212d172acaaf","url":"https://ncert.nic.in/textbook/pdf/hess205.pdf","locator":"PDF pp. 1–2, lines 17–30","source_authority":"National Council of Educational Research and Training (NCERT), Our Pasts III, ch. 5, When People Revolt: 1857 and After, 2024–25 reprint; actual PDF passage inspected 2026-10-19","independence_assessment":"One government-published secondary educational synthesis. It supports these narrowly worded, noncontroversial assertions; no independent primary record is claimed.","original_source_inspected":true}],"verification_rationale":"The requested pension and refusal are explicit; the broader explanatory relationship is narrowed to the source’s juxtaposition.","original_source_inspected":true,"material_limitation":"Secondary textbook synthesis, not direct inspection of nineteenth-century records.","removal_reason":null,