INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('61e944ef-a848-4865-b28b-7ab1b56dc7eb'::uuid,'REVISE AND APPROVE','{"claim_id":"61e944ef-a848-4865-b28b-7ab1b56dc7eb","personality_id":"2abfe46e-6b67-4fba-a6c1-e5864f69bf35","personality":"Satyajit Ray","original_claim_text":"The Academy honored Ray for a lifetime body of work rather than awarding a competitive Oscar to Pather Panchali or another individual film.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["119d6b37-13d5-4af9-8f21-ad2252084141"],"original_passage_ids":["61b1cdfa-7bdf-4dfc-9b3e-f454313cbb06"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"At the 1992 Academy Awards, Satyajit Ray received an Honorary Award recognizing his filmmaking, rather than an award for an individual film.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"url":"https://www.oscars.org/oscars/ceremonies/1992/memorable-moments","locator":"Honorary Award, lines 79–80","source_id":null,"source_authority":"Academy of Motion Picture Arts and Sciences official awards record, live page inspected in batch 001","independence_assessment":"Original issuing institution; no independent corroboration is inferred from this source alone.","original_source_inspected":true}],"verification_rationale":"The Academy''s own ceremony record identifies an Honorary Award to Ray and names no individual film in the citation. The original phrase ''lifetime body of work'' was broader than the formal citation and was narrowed. The separately linked awards-database URL was not needed for this check.","original_source_inspected":true,"material_limitation":"Institutional record supports its own mission, award, or designation; broader causal history requires separate corroboration.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
