INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('0d6e0dc3-6b43-453e-b1f3-8b8abf08e8ab'::uuid,'REVISE AND APPROVE','{"claim_id":"0d6e0dc3-6b43-453e-b1f3-8b8abf08e8ab","personality_id":"2abfe46e-6b67-4fba-a6c1-e5864f69bf35","personality":"Satyajit Ray","original_claim_text":"The Academy’s citation explicitly recognized Ray’s international influence on filmmakers and audiences, evidence of institutional reception rather than a neutral measure of all influence.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["119d6b37-13d5-4af9-8f21-ad2252084141"],"original_passage_ids":["5bf3232f-e478-416b-afd9-4d1670462198"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The Academy''s 1992 Honorary Award citation credited Ray with influence on filmmakers and audiences worldwide; this records the Academy''s judgment of his reception.","epistemic_type":"MODERN_RECEPTION","evidence_references":[{"url":"https://www.oscars.org/oscars/ceremonies/1992/memorable-moments","locator":"Honorary Award citation, lines 79–80","source_id":null,"source_authority":"Academy of Motion Picture Arts and Sciences official awards record, live page inspected in batch 001","independence_assessment":"Original issuing institution; no independent corroboration is inferred from this source alone.","original_source_inspected":true}],"verification_rationale":"The Academy citation explicitly asserts the influence. Framing it as the Academy''s judgment preserves the difference between an institutional honor and an independently measured effect.","original_source_inspected":true,"material_limitation":"Institutional record supports its own mission, award, or designation; broader causal history requires separate corroboration.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
