INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('25c136e6-160b-4f03-ad54-859388b163ff'::uuid,'REVISE AND APPROVE','{"claim_id":"25c136e6-160b-4f03-ad54-859388b163ff","personality_id":"7dd19728-dbbf-4288-a3ec-ddb57806b863","personality":"Savitribai Phule","original_claim_text":"An 1851–52 education report quoted by Hari Narake records Jyotirao educating Savitribai at home and preparing her to teach, evidence that her formal public role followed learning after marriage.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["66e60995-852c-477c-8aaa-4ce3fe4c6d13"],"original_passage_ids":["b014ee98-90ab-4138-96a7-c9a40aaa18bb"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Hari Narake cites government records for Jyotirao Phule''s education of Savitribai at home after marriage and an 1851 Bombay Guardian report concerning her further education; he also records her teacher training in Ahmednagar and Pune.","epistemic_type":"SCHOLARLY_ATTRIBUTION","evidence_references":[{"source_id":"66e60995-852c-477c-8aaa-4ce3fe4c6d13","url":"https://www.ncert.nic.in/pdf/publication/otherpublications/Memorial-Lectures-Series/FINAL%20COVER%20OF%20SAVIRTIBAI%20PHULE.pdf","locator":"PDF pp. 10–11, lines 300–311","source_authority":"NCERT 2009 memorial booklet; historian Hari Narake''s essay or reproduced source text, full PDF inspected 2026-10-19","independence_assessment":"One scholarly source work, sometimes quoting archival material; its reproduced records are not counted as independent corroboration without the archival originals.","original_source_inspected":true}],"verification_rationale":"The original conflated government records with the newspaper report. Narake distinguishes them.","original_source_inspected":true,"material_limitation":"NCERT booklet is a retrospective secondary account; archival originals and conflicting dates require separate checking for broader claims.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
