INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('8787018f-bd39-4e41-ba16-55da7c58fc1e'::uuid,'REVISE AND APPROVE','{"claim_id":"8787018f-bd39-4e41-ba16-55da7c58fc1e","personality_id":"7dd19728-dbbf-4288-a3ec-ddb57806b863","personality":"Savitribai Phule","original_claim_text":"Savitribai died of plague on 10 March 1897 while involved in epidemic relief; the NCERT essay body and the university graphic biography agree on this date, unlike the NCERT cover’s inconsistent 19 March entry.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["66e60995-852c-477c-8aaa-4ce3fe4c6d13"],"original_passage_ids":["27ca5374-cdce-47e3-b57a-c7527d7c2862"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Hari Narake''s essay dates Savitribai Phule''s death during plague relief to 10 March 1897, while the cover chronology of the same NCERT booklet says 19 March; the discrepancy requires checking against a contemporary death record.","epistemic_type":"CONTESTED","evidence_references":[{"source_id":"66e60995-852c-477c-8aaa-4ce3fe4c6d13","url":"https://www.ncert.nic.in/pdf/publication/otherpublications/Memorial-Lectures-Series/FINAL%20COVER%20OF%20SAVIRTIBAI%20PHULE.pdf","locator":"PDF cover p. 0, line 48; essay pp. 25–26, lines 875–887","source_authority":"NCERT 2009 memorial booklet; historian Hari Narake''s essay or reproduced source text, full PDF inspected 2026-10-19","independence_assessment":"One scholarly source work, sometimes quoting archival material; its reproduced records are not counted as independent corroboration without the archival originals.","original_source_inspected":true}],"verification_rationale":"The conflict is visible within the inspected NCERT booklet. The original''s separate university biography agreement was not checked here and is omitted.","original_source_inspected":true,"material_limitation":"NCERT booklet is a retrospective secondary account; archival originals and conflicting dates require separate checking for broader claims.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
