INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('e71d639e-7dfa-4afa-9efc-cad089bec84c'::uuid,'APPROVE','{"claim_id":"e71d639e-7dfa-4afa-9efc-cad089bec84c","personality_id":"7dd19728-dbbf-4288-a3ec-ddb57806b863","personality":"Savitribai Phule","original_claim_text":"The educational ideal attributed to the Phules emphasized judging truth and untruth and encouraging creativity, rather than treating schooling as memorization alone.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["66e60995-852c-477c-8aaa-4ce3fe4c6d13"],"original_passage_ids":["93fc7cf5-f192-4fef-a151-54a293b04f76"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The educational ideal attributed to the Phules emphasized judging truth and untruth and encouraging creativity, rather than treating schooling as memorization alone.","epistemic_type":"SCHOLARLY_ATTRIBUTION","evidence_references":[{"source_id":"66e60995-852c-477c-8aaa-4ce3fe4c6d13","url":"https://www.ncert.nic.in/pdf/publication/otherpublications/Memorial-Lectures-Series/FINAL%20COVER%20OF%20SAVIRTIBAI%20PHULE.pdf","locator":"PDF pp. 16–17, lines 544–557","source_authority":"NCERT 2009 memorial booklet; historian Hari Narake''s essay or reproduced source text, full PDF inspected 2026-10-19","independence_assessment":"One scholarly source work, sometimes quoting archival material; its reproduced records are not counted as independent corroboration without the archival originals.","original_source_inspected":true}],"verification_rationale":"Narake states the right/wrong and truth/untruth ideal and describes encouragement of creativity.","original_source_inspected":true,"material_limitation":"NCERT booklet is a retrospective secondary account; archival originals and conflicting dates require separate checking for broader claims.","removal_reason":null,"applied_to_is