INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('6e42d0c1-5b81-4d73-a01d-ec209673256c'::uuid,'REVISE AND APPROVE','{"claim_id":"6e42d0c1-5b81-4d73-a01d-ec209673256c","personality_id":"7dd19728-dbbf-4288-a3ec-ddb57806b863","personality":"Savitribai Phule","original_claim_text":"Descriptions of the Phules as pioneers must be qualified: Narake’s history mentions an existing missionary girls’ school at Ahmednagar, so “India’s first girls’ school” should not be read as a literal claim that all girls’ schooling began with them.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["66e60995-852c-477c-8aaa-4ce3fe4c6d13"],"original_passage_ids":["4483d56c-4d47-4131-9182-ba8112bb8129"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Hari Narake describes Jyotirao Phule visiting Farrar''s existing girls'' school at Ahmednagar before beginning the Phules'' school work in Pune; a claim that they founded India''s first girls'' school needs this qualification.","epistemic_type":"SCHOLARLY_ATTRIBUTION","evidence_references":[{"source_id":"66e60995-852c-477c-8aaa-4ce3fe4c6d13","url":"https://www.ncert.nic.in/pdf/publication/otherpublications/Memorial-Lectures-Series/FINAL%20COVER%20OF%20SAVIRTIBAI%20PHULE.pdf","locator":"PDF p. 13, lines 401–409","source_authority":"NCERT 2009 memorial booklet; historian Hari Narake''s essay or reproduced source text, full PDF inspected 2026-10-19","independence_assessment":"One scholarly source work, sometimes quoting archival material; its reproduced records are not counted as independent corroboration without the archival originals.","original_source_inspected":true}],"verification_rationale":"The inspected passage directly establishes an earlier girls'' school in Ahmednagar; the revised wording avoids an unqualified national first.","original_source_inspected":true,"material_limitation":"NCERT booklet is a retrospective secondary account; archival originals and conflicting dates require separate checking for broader claims.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Hari Narake describes Jyotirao Phule visiting Farrar''s existing girls'' school at Ahmednagar before beginning the Phules'' school work in Pune; a claim that they founded India''s first girls'' school needs this qualification.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='6e42d0c1-5b81-4d73-a01d-ec209673256c'::uuid;
