INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('1e794aaa-d278-41d9-b460-bcd635f3ac3f'::uuid,'APPROVE','{"claim_id":"1e794aaa-d278-41d9-b460-bcd635f3ac3f","personality_id":"1f893928-3c09-424a-b513-c62893e57cb8","personality":"Srinivasa Ramanujan","original_claim_text":"Ramanujan supported himself as a clerk at the Madras Port Trust while continuing mathematical research.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["b436d76b-b701-4a8b-9b5b-51b60b92f7b0"],"original_passage_ids":["490ed87b-f5a6-4539-a1e2-7e8f35b24314"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Ramanujan supported himself as a clerk at the Madras Port Trust while continuing mathematical research.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":"b436d76b-b701-4a8b-9b5b-51b60b92f7b0","url":"https://mathshistory.st-andrews.ac.uk/Biographies/Ramanujan/","locator":"lines 37–47; compare Hardy PDF pp. 1–2, lines 43–50, 86–94","source_authority":"MacTutor History of Mathematics, University of St Andrews, J. J. O’Connor and E. F. Robertson, inspected 2026-10-19","independence_assessment":"One directly inspected work; supporting contemporary or scholarly corroboration is identified in the rationale where checked. Repetition of the same underlying account is not counted as independent evidence.","original_source_inspected":true}],"verification_rationale":"MacTutor and Hardy’s obituary both describe Port Trust clerkship and concurrent mathematical work; the obituary embeds Ramanujan’s own statement.","original_source_inspected":true,"material_limitation":"Hardy’s obituary misdates the start of the clerkship to 1911; MacTutor says 1 March 1912. The claim does not specify the date.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
