INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('fa02e01d-7471-4263-9266-599ac65ce5bc'::uuid,'APPROVE','{"claim_id":"fa02e01d-7471-4263-9266-599ac65ce5bc","personality_id":"1f893928-3c09-424a-b513-c62893e57cb8","personality":"Srinivasa Ramanujan","original_claim_text":"Without a university mathematics education or regular access to current research, Ramanujan continued developing ideas independently.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["b436d76b-b701-4a8b-9b5b-51b60b92f7b0"],"original_passage_ids":["d1313020-b72a-41c1-803b-161ece9c6e02"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Without a university mathematics education or regular access to current research, Ramanujan continued developing ideas independently.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"source_id":"b436d76b-b701-4a8b-9b5b-51b60b92f7b0","url":"https://mathshistory.st-andrews.ac.uk/Biographies/Ramanujan/","locator":"lines 28–34; compare Hardy PDF pp. 2, 10, lines 86–95, 434–441","source_authority":"MacTutor History of Mathematics, University of St Andrews, J. J. O’Connor and E. F. Robertson, inspected 2026-10-19","independence_assessment":"One directly inspected work; supporting contemporary or scholarly corroboration is identified in the rationale where checked. Repetition of the same underlying account is not counted as independent evidence.","original_source_inspected":true}],"verification_rationale":"MacTutor documents failed degree examinations and independent work; Ramanujan’s letter and Hardy’s assessment confirm limited conventional training.","original_source_inspected":true,"material_limitation":"Regular access to current literature cannot be precisely quantified from these sources; the claim says only that it was lacking.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
