INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('d5ca29df-8313-4800-9d7e-2fcf755eecba'::uuid,'APPROVE','{"claim_id":"d5ca29df-8313-4800-9d7e-2fcf755eecba","personality_id":"9a66a004-b1ce-429d-946e-715ae059f730","personality":"Verghese Kurien","original_claim_text":"NDDB reports 43,000 village cooperatives and 4.25 million producer members by 1985; these are programme records, not a count of all Indian dairy farmers.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["3cd25b95-a326-4c77-b5fb-8a274e7827d3"],"original_passage_ids":["529b88cf-8cf1-41ff-a318-b9b11052de28"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"NDDB reports 43,000 village cooperatives and 4.25 million producer members by 1985; these are programme records, not a count of all Indian dairy farmers.","epistemic_type":"SCHOLARLY_ATTRIBUTION","evidence_references":[{"url":"https://www.nddb.coop/about/genesis/flood","locator":"lines 260–263","source_id":"3cd25b95-a326-4c77-b5fb-8a274e7827d3","source_authority":"National Dairy Development Board programme history; issuing institution; live passage inspected 2026-10-19","independence_assessment":"Single original or institutional source. No second independent source is inferred.","original_source_inspected":true}],"verification_rationale":"NDDB gives both figures and the claim properly identifies them as programme counts.","original_source_inspected":true,"material_limitation":"Institutional accounts and first-person recollections support the attributed or narrow claim; broader historical interpretations need independent corroboration.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
