INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('e9171056-70a4-45f2-b42f-9d6123d49706'::uuid,'REVISE AND APPROVE','{"claim_id":"e9171056-70a4-45f2-b42f-9d6123d49706","personality_id":"9a66a004-b1ce-429d-946e-715ae059f730","personality":"Verghese Kurien","original_claim_text":"Kurien''s major contribution was institutional rather than solitary: he helped connect engineering, professional management, farmer ownership, processing, and national market infrastructure in the Anand pattern and Operation Flood.","original_review_status":"approved","original_approval_origin":"human_manual","original_source_ids":["162fa362-1a24-42ce-92fe-64a13cc81160","3cd25b95-a326-4c77-b5fb-8a274e7827d3","3d12e474-d1b1-4b71-8e55-b354470ffbb7"],"original_passage_ids":["a1904833-8b29-40d2-b3a4-d331764b51b7","3a6bf761-ffb2-4b03-be0f-b7995755df5b","57bf10d3-eac6-4244-b3bd-64d54aea9faf"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Kurien described Operation Flood as a combination of farmer-owned cooperatives, professional management, processing, markets, and supportive policy, rather than an individual technological achievement.","epistemic_type":"SCHOLARLY_INTERPRETATION","evidence_references":[{"source_id":null,"url":"https://drkurien.com/october-17-1989/","locator":"Acceptance speech, lines 21–24 and 37","source_authority":"Kurien''s published 1989 acceptance speech","independence_assessment":"Distinct original speech or institutional issuer account; additional institutional corroboration is named in the rationale where used.","original_source_inspected":true}],"verification_rationale":"His own speech supplies the institutional synthesis; WFP tribute lines 48–56 independently describes the multi-actor programme. The original broader significance claim was narrowed and attributed.","original_source_inspected":true,"material_limitation":"The magnitude of national impact requires separate evaluation.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Kurien described Operation Flood as a combination of farmer-owned cooperatives, professional management, processing, markets, and supportive policy, rather than an individual technological achievement.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='e9171056-70a4-45f2-b42f-9d6123d49706'::uuid;
