INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('6550d9a8-9e99-421d-be2c-be60a0155d07'::uuid,'REVISE AND APPROVE','{"claim_id":"6550d9a8-9e99-421d-be2c-be60a0155d07","personality_id":"9a66a004-b1ce-429d-946e-715ae059f730","personality":"Verghese Kurien","original_claim_text":"Operation Flood began in 1970 to scale the Anand pattern nationally through producer cooperatives, urban markets and dairy services.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["3cd25b95-a326-4c77-b5fb-8a274e7827d3"],"original_passage_ids":["680cec3a-ab5d-497c-abcb-6e17870d48ac"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Operation Flood began in 1970 and used village milk-producer cooperatives, urban markets and dairy services to expand milk production and marketing.","epistemic_type":"HISTORICAL_FACT","evidence_references":[{"url":"https://www.nddb.coop/about/genesis/flood","locator":"lines 237–257","source_id":"3cd25b95-a326-4c77-b5fb-8a274e7827d3","source_authority":"National Dairy Development Board programme history; issuing institution; live passage inspected 2026-10-19","independence_assessment":"Single original or institutional source. No second independent source is inferred.","original_source_inspected":true}],"verification_rationale":"The page supports launch and structure, but does not itself use the claim’s Anand-pattern formulation.","original_source_inspected":true,"material_limitation":"Institutional accounts and first-person recollections support the attributed or narrow claim; broader historical interpretations need independent corroboration.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
