INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('7ac5f497-5e28-447d-9141-3aedfa8d6db1'::uuid,'REVISE AND APPROVE','{"claim_id":"7ac5f497-5e28-447d-9141-3aedfa8d6db1","personality_id":"9a66a004-b1ce-429d-946e-715ae059f730","personality":"Verghese Kurien","original_claim_text":"NDDB states three linked objectives: more milk, higher rural incomes and reasonable consumer prices; each depended on a functioning supply chain rather than output alone.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["3cd25b95-a326-4c77-b5fb-8a274e7827d3"],"original_passage_ids":["d0c2cb72-7024-486b-a7a8-199d286c2ec6"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"NDDB states Operation Flood’s three objectives as increasing milk production, augmenting rural incomes and providing reasonable prices for consumers.","epistemic_type":"SCHOLARLY_ATTRIBUTION","evidence_references":[{"url":"https://www.nddb.coop/about/genesis/flood","locator":"lines 237–245","source_id":"3cd25b95-a326-4c77-b5fb-8a274e7827d3","source_authority":"National Dairy Development Board programme history; issuing institution; live passage inspected 2026-10-19","independence_assessment":"Single original or institutional source. No second independent source is inferred.","original_source_inspected":true}],"verification_rationale":"The three objectives are direct; the original supply-chain dependence is analysis beyond this passage.","original_source_inspected":true,"material_limitation":"Institutional accounts and first-person recollections support the attributed or narrow claim; broader historical interpretations need independent corroboration.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
