INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('78d42ac5-b62c-42cb-bf06-01f5ca27490f'::uuid,'REVISE AND APPROVE','{"claim_id":"78d42ac5-b62c-42cb-bf06-01f5ca27490f","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"Rigveda 3.62.10 remains directly accessible through the Government of India’s Vedic Heritage Portal with preserved text and recitation resources. Contemporary relevance can therefore be described in terms of continued access to the mantra without inventing popularity statistics.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["c2d10c6c-8da2-4f5a-becf-93b160eb267b"],"original_passage_ids":["dbcfbb5a-8120-4b13-9f5a-9d266e46e0d0"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The Government of India’s Vedic Heritage Portal provides the text of Rigveda 3.62.10 and links to recitation material.","epistemic_type":"MODERN_RECEPTION","evidence_references":[{"source_id":"c2d10c6c-8da2-4f5a-becf-93b160eb267b","url":"https://vedicheritage.gov.in/hi/samhitas/rigveda/shakala-samhita/rigveda-shakala-samhita-mandal-03-sukta-062/","locator":"Rigveda 3.62.10, portal lines 407–409, 427","source_authority":"Government of India Vedic Heritage Portal, Rigveda 3.62 Sanskrit text and seer metadata; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The portal supplies the verse and a recitation-video link; the claim confines relevance to access. Coordinator removed the unsupported general conclusion about contemporary relevance.","original_source_inspected":true,"material_limitation":"Traditional rishi attribution and hymn text; not independent proof of single-person authorship.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
