INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('921abb4e-69b7-4225-92ef-fddac41f8f66'::uuid,'REVISE AND APPROVE','{"claim_id":"921abb4e-69b7-4225-92ef-fddac41f8f66","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"The Menaka episode is not just a seduction anecdote in Bala Kanda: the text emphasizes a ten-year lapse, Vishvamitra''s later grief, recognition of interruption, and return to austerity.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["2025af50-f65e-4a13-b670-adc6a2a0e3dc","d39ddd21-67b7-4c7c-bfae-ea1f99918420"],"original_passage_ids":["1c601c57-75d6-404c-868e-11361f2be7ee","9c862712-4d53-404e-a5bb-1c24e1296451"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Bala Kanda 1.63 narrates a ten-year stay with Menaka, Vishvamitra’s regret over interrupted austerity, and his return to severe tapas.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"d39ddd21-67b7-4c7c-bfae-ea1f99918420","url":"https://www.valmikiramayan.net/utf8/baala/sarga63/bala_63_prose.htm","locator":"Bala Kanda 1.63.4–16","source_authority":"Valmiki Ramayana, Bala Kanda 1.63, Desiraju Hanumanta Rao English rendering; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"Removed the editorial phrase “not just a seduction anecdote”.","original_source_inspected":true,"material_limitation":"Epic sacred narrative; the passage does not independently establish historical biography or supernatural events.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
