INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('be9c9822-362d-48f6-9964-38c02d26b3c6'::uuid,'REVISE AND APPROVE','{"claim_id":"be9c9822-362d-48f6-9964-38c02d26b3c6","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"The Rambha episode should not be reduced to a story of supernatural cursing; its narrative function also includes Vishvamitra''s recognition that anger has disrupted his ascetic goal.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["8d1e7888-6577-4564-b935-96ed0ae1b902"],"original_passage_ids":["2a5bae86-6077-4fd8-8d21-59b2a47b760a","515003fb-3676-4dbd-8abb-a58e725319ce"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Bala Kanda 1.64 narrates Vishvamitra cursing Rambha, regretting his anger, and resolving not to succumb to anger again.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"8d1e7888-6577-4564-b935-96ed0ae1b902","url":"https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm","locator":"Bala Kanda 1.64.11–17","source_authority":"Valmiki Ramayana, Bala Kanda 1.64, Sanskrit text with Desiraju Hanumanta Rao English rendering; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The chapter directly supports this sequence; “narrative function” was an interpretation.","original_source_inspected":true,"material_limitation":"Epic sacred narrative; the passage does not independently establish historical biography or supernatural events.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
