INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('21eef295-6488-45ca-b86e-fc5ae5e7c25d'::uuid,'APPROVE','{"claim_id":"21eef295-6488-45ca-b86e-fc5ae5e7c25d","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"The Brahmarshi transformation is securely a fact about the Ramayana narrative even when questions about the historical individual remain open.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["b1ff445c-d9d0-4f8e-a28f-f3a8053787ad"],"original_passage_ids":["d5e6cd91-c377-43d8-a3aa-a6233c8d0a82","ef5de7fd-af8f-4eaa-9685-ac9b0a43aa7d"],"audit_publication_gate":"EXCLUDE_FROM_STRICT_RELEASE_UNTIL_EVIDENCE_REPAIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The Brahmarshi transformation is securely a fact about the Ramayana narrative even when questions about the historical individual remain open.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"b1ff445c-d9d0-4f8e-a28f-f3a8053787ad","url":"https://www.valmikiramayan.net/utf8/baala/sarga65/balasans65.htm.orig","locator":"Bala Kanda 1.65.19–28","source_authority":"Valmiki Ramayana, Bala Kanda 1.65, Sanskrit text with Desiraju Hanumanta Rao English rendering; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"This is a fact about the epic narrative, not about independently established biography.","original_source_inspected":true,"material_limitation":"Epic sacred narrative; the passage does not independently establish historical biography or supernatural events.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
