INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('5909bf8a-b6ac-425f-b74c-a9df3fe197de'::uuid,'REVISE AND APPROVE','{"claim_id":"5909bf8a-b6ac-425f-b74c-a9df3fe197de","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"The intermediate Maharshi title in Bala Kanda 1.63 should be reviewed alongside the earlier Rajarshi and later Brahmarshi labels so the profile represents a sequence rather than treating all honorifics as simultaneous equivalents.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["2025af50-f65e-4a13-b670-adc6a2a0e3dc","d39ddd21-67b7-4c7c-bfae-ea1f99918420"],"original_passage_ids":["1c601c57-75d6-404c-868e-11361f2be7ee"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Bala Kanda 1.63 depicts Maharshi as an intermediate recognition: after another long austerity Brahma grants that title, but says Vishvamitra has not yet conquered his senses.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"d39ddd21-67b7-4c7c-bfae-ea1f99918420","url":"https://www.valmikiramayan.net/utf8/baala/sarga63/bala_63_prose.htm","locator":"Bala Kanda 1.63.17–20","source_authority":"Valmiki Ramayana, Bala Kanda 1.63, Desiraju Hanumanta Rao English rendering; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"Narrowed cross-chapter editorial advice to the inspected episode.","original_source_inspected":true,"material_limitation":"Epic sacred narrative; the passage does not independently establish historical biography or supernatural events.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
