INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('0207c641-72a8-456d-ad19-97221c8b97e6'::uuid,'REVISE AND APPROVE','{"claim_id":"0207c641-72a8-456d-ad19-97221c8b97e6","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"Rigveda 3.62.10 invokes Savitar’s radiance and asks that it impel or guide human thought/intellect. Within the Vishvamitra textual corpus, this is a central spiritual-intellectual motif grounded directly in the mantra.","original_review_status":"approved","original_approval_origin":"imported_existing","original_source_ids":["c2d10c6c-8da2-4f5a-becf-93b160eb267b"],"original_passage_ids":["dbcfbb5a-8120-4b13-9f5a-9d266e46e0d0"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Rigveda 3.62.10 invokes Savitar’s divine radiance and asks that it impel our thoughts (dhiyo). The Vedic Heritage Portal places it in a Savitar section associated by seer metadata with Gathina Vishvamitra.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"c2d10c6c-8da2-4f5a-becf-93b160eb267b","url":"https://vedicheritage.gov.in/hi/samhitas/rigveda/shakala-samhita/rigveda-shakala-samhita-mandal-03-sukta-062/","locator":"Rigveda 3.62.10, portal lines 414, 427","source_authority":"Government of India Vedic Heritage Portal, Rigveda 3.62 Sanskrit text and seer metadata; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The Sanskrit directly supports Savitar and dhiyo; “central spiritual-intellectual motif” was interpretive.","original_source_inspected":true,"material_limitation":"Traditional rishi attribution and hymn text; not 