INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('cde8a2ea-9593-4a01-ad44-d58967d139c0'::uuid,'REMOVE FROM ACTIVE CORPUS','{"claim_id":"cde8a2ea-9593-4a01-ad44-d58967d139c0","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"Vishvamitra''s weapon instruction to Rama includes how to neutralize or withdraw an astra after it has been invoked, so the teaching tradition represented in Bala Kanda values command over power rather than mere possession of power.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["7aa52a0f-84ca-425a-8671-21e4e2c4e6c0","b829b48c-8875-4cb2-802b-bcb274d48fa9"],"original_passage_ids":["618e42b7-09de-4ee2-9794-6231f2f36deb"],"audit_publication_gate":"EXCLUDE_FROM_STRICT_RELEASE_UNTIL_EVIDENCE_REPAIRED","review_state":"evidence_assessed","decision":"REMOVE FROM ACTIVE CORPUS","final_proposed_wording":"Vishvamitra''s weapon instruction to Rama includes how to neutralize or withdraw an astra after it has been invoked, so the teaching tradition represented in Bala Kanda values command over power rather than mere possession of power.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"b829b48c-8875-4cb2-802b-bcb274d48fa9","url":"https://www.valmikiramayan.net/utf8/baala/sarga28/bala_28_prose.htm","locator":"Bala Kanda 1.28.1–5, prose lines 9–14","source_authority":"Valmiki Ramayana, Bala Kanda 1.28, Desiraju Hanumanta Rao English rendering; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"Substance duplicates retained and more narrowly worded claim 2544eb75.","original_source_inspected":true,"material_limitation":"Epic sacred narrati