INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('35c9c378-40ea-4ff7-a1ac-9681cd4cf575'::uuid,'REVISE AND APPROVE','{"claim_id":"35c9c378-40ea-4ff7-a1ac-9681cd4cf575","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"The relationship is not merely advisory: Dasharatha ultimately entrusts Rama to Vishvamitra, placing the sage in temporary guardianship and instruction of the prince.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"],"original_passage_ids":["3e790a17-403e-47fd-b349-d85f9c4d92bd","b6e661c7-935d-4437-966f-55bbe4dbc538"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"In Bala Kanda 1.22, Dasharatha entrusts Rama to Vishvamitra, who then guides and instructs him.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"4772171e-b53b-4ae5-9ffa-e6edf7a8f9de","url":"https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm","locator":"Bala Kanda 1.22.2–3, 11–22","source_authority":"Valmiki Ramayana, Bala Kanda 1.22, Sanskrit text with Desiraju Hanumanta Rao English rendering; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"Entrustment and teaching are explicit; guardianship is an interpretive label.","original_source_inspected":true,"material_limitation":"Epic sacred narrative; the passage does not independently establish historical biography or supernatural events.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
