INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('79dc18aa-e604-40bf-a754-553f10851aa9'::uuid,'REVISE AND APPROVE','{"claim_id":"79dc18aa-e604-40bf-a754-553f10851aa9","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"Bala Kanda attributes extraordinary effects to Bala and Atibala—protection from fatigue, hunger, thirst, and attack while asleep—within the story-world.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"],"original_passage_ids":["271446df-1b16-4af1-b22d-f06365591e27"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"In Vishvamitra’s speech in Bala Kanda 1.22, Bala and Atibala are said to protect Rama from fatigue and attacks while asleep, and to avert hunger and thirst. These are claims within the epic.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"4772171e-b53b-4ae5-9ffa-e6edf7a8f9de","url":"https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm","locator":"Bala Kanda 1.22.12–13, 17","source_authority":"Valmiki Ramayana, Bala Kanda 1.22, Sanskrit text with Desiraju Hanumanta Rao English rendering; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"Direct speech presents extraordinary effects; wording attributes them to the text.","original_source_inspected":true,"material_limitation":"Epic sacred narrative; the passage does not independently establish historical biography or supernatural events.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='In Vishvamitra’s speech in Bala Kanda 1.22, Bala and Atibala are said to protect Rama from fatigue and attacks while asleep, and to avert hunger and thirst. These are claims within the epic.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='79dc18aa-e604-40bf-a754-553f10851aa9'::uuid;
