INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('bf922fd9-48be-4064-8c41-eed5a28c9adc'::uuid,'REVISE AND APPROVE','{"claim_id":"bf922fd9-48be-4064-8c41-eed5a28c9adc","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"Bala Kanda 1.21 attributes to Vishvamitra knowledge of weapons unknown even to other divine and nonhuman beings; this is a statement inside Vasistha''s epic speech and should be labeled accordingly.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["0537c002-ff50-437a-88f6-1ca1f43572cf","9227358e-67a7-46f5-a873-bb5582ebb893"],"original_passage_ids":["16e8b4c0-c2b9-44bb-b4df-2f3f97395940","eb13ef00-ba13-431c-9957-e70d915433bf"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"In Vasistha’s speech in Bala Kanda 1.21, Vishvamitra is praised for knowledge of many astras and described as beyond the knowledge of gods, sages, and other beings. This is epic praise within Vasistha’s speech.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"9227358e-67a7-46f5-a873-bb5582ebb893","url":"https://www.valmikiramayan.net/utf8/baala/sarga21/bala_21_prose.htm","locator":"Bala Kanda 1.21.11–12","source_authority":"Valmiki Ramayana, Bala Kanda 1.21, Desiraju Hanumanta Rao prose English rendering; corresponding Sanskrit verse page also checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The verse praises his knowledge and says others cannot know him; it does not literally say that the astras are unknown to all those beings.","original_source_inspected":true,"material_limitation":"Epic sacred narrative; the passage does not independently establish historical biography or supernatural events.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='In Vasistha’s speech in Bala Kanda 1.21, Vishvamitra is praised for knowledge of many astras and described as beyond the knowledge of gods, sages, and other beings. This is epic praise within Vasistha’s speech.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='bf922fd9-48be-4064-8c41-eed5a28c9adc'::uuid;
