INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('414589e3-ad4f-4f1c-941a-b93274ca0444'::uuid,'REVISE AND APPROVE','{"claim_id":"414589e3-ad4f-4f1c-941a-b93274ca0444","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"Vishvamitra''s instruction to Rama includes both invocation and withdrawal procedures for astras, presenting restraint and reversibility as part of competent sacred-weapon practice.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["7aa52a0f-84ca-425a-8671-21e4e2c4e6c0","b829b48c-8875-4cb2-802b-bcb274d48fa9"],"original_passage_ids":[],"audit_publication_gate":"EXCLUDE_FROM_STRICT_RELEASE_UNTIL_EVIDENCE_REPAIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Bala Kanda 1.28 presents instruction in neutralizing astras after Rama has received projectile astras. This is part of the epic’s martial instruction narrative.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"b829b48c-8875-4cb2-802b-bcb274d48fa9","url":"https://www.valmikiramayan.net/utf8/baala/sarga28/bala_28_prose.htm","locator":"Bala Kanda 1.28.1–5, prose lines 9–14","source_authority":"Valmiki Ramayana, Bala Kanda 1.28, Desiraju Hanumanta Rao English rendering; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The passage supports neutralization; “restraint and reversibility as competent practice” is modern interpretation.","original_source_inspected":true,"material_limitation":"Epic sacred narrative; the passage does not independently establish historical biography or supernatural events.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Bala Kanda 1.28 presents instruction in neutralizing astras after Rama has received projectile astras. This is part of the epic’s martial instruction narrative.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='414589e3-ad4f-4f1c-941a-b93274ca0444'::uuid;
