INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('99acbe03-a70c-4ad2-ba5c-4b099da1e780'::uuid,'APPROVE','{"claim_id":"99acbe03-a70c-4ad2-ba5c-4b099da1e780","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"The epic portrayal treats mastery of anger as part of Vishvamitra''s ascetic project, not merely acquisition of supernatural power.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["8d1e7888-6577-4564-b935-96ed0ae1b902"],"original_passage_ids":["2a5bae86-6077-4fd8-8d21-59b2a47b760a","515003fb-3676-4dbd-8abb-a58e725319ce"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The epic portrayal treats mastery of anger as part of Vishvamitra''s ascetic project, not merely acquisition of supernatural power.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"8d1e7888-6577-4564-b935-96ed0ae1b902","url":"https://www.valmikiramayan.net/utf8/baala/sarga64/balasans64.htm","locator":"Bala Kanda 1.64.11–17","source_authority":"Valmiki Ramayana, Bala Kanda 1.64, Sanskrit text with Desiraju Hanumanta Rao English rendering; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The narrative expressly treats anger as undoing ascetic merit.","original_source_inspected":true,"material_limitation":"Epic sacred narrative; the passage does not independently establish historical biography or supernatural events.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
