INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('b070cd29-c722-4478-b2ce-56ff7085e386'::uuid,'REVISE AND APPROVE','{"claim_id":"b070cd29-c722-4478-b2ce-56ff7085e386","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"Bala and Atibala are presented as disciplines transmitted by Vishvamitra to Rama, and the text links their efficacy to practice and ascetic cultivation.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["4772171e-b53b-4ae5-9ffa-e6edf7a8f9de"],"original_passage_ids":["347af684-3faf-459c-902b-b4f21353fb0c","b6e661c7-935d-4437-966f-55bbe4dbc538"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"Bala Kanda 1.22 presents Bala and Atibala as teachings Vishvamitra transmits to Rama and says their practice and ascetic cultivation produce effects within the story.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"4772171e-b53b-4ae5-9ffa-e6edf7a8f9de","url":"https://www.valmikiramayan.net/utf8/baala/sarga22/balasans22.htm","locator":"Bala Kanda 1.22.11–12, 19–22","source_authority":"Valmiki Ramayana, Bala Kanda 1.22, Sanskrit text with Desiraju Hanumanta Rao English rendering; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"Narrowed from general disciplines to the text’s teaching scene.","original_source_inspected":true,"material_limitation":"Epic sacred narrative; the passage does not independently establish historical biography or supernatural events.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Bala Kanda 1.22 presents Bala and Atibala as teachings Vishvamitra transmits to Rama and says their practice and ascetic cultivation produce effects within the story.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='b070cd29-c722-4478-b2ce-56ff7085e386'::uuid;
