INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('8e7bea8b-3659-4a65-9118-ceaf8e12da55'::uuid,'APPROVE','{"claim_id":"8e7bea8b-3659-4a65-9118-ceaf8e12da55","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"Rigveda 3.1 identifies Gathina Vishvamitra as the rishi of the hymn to Agni.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["5bef2a36-07ca-4a1f-91a1-1454275e2dfa"],"original_passage_ids":["eee5715c-a576-45d8-89da-c841232e4f80"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Rigveda 3.1 identifies Gathina Vishvamitra as the rishi of the hymn to Agni.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"5bef2a36-07ca-4a1f-91a1-1454275e2dfa","url":"https://vedicheritage.gov.in/samhitas/rigveda/shakala-samhita/mandal-03/","locator":"Rigveda Rigveda 3.1 seer metadata, portal line 414","source_authority":"Government of India Vedic Heritage Portal, Rigveda 3.1 Sanskrit text and seer metadata; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"The portal explicitly identifies Gathina Vishvamitra as seer and Agni as deity. This is a traditional rishi attribution, not modern authorship proof.","original_source_inspected":true,"material_limitation":"Traditional rishi attribution and hymn text; not independent proof of single-person authorship.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
