INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('95e35dcf-d4fa-4896-bc02-88d10f7fcc83'::uuid,'APPROVE','{"claim_id":"95e35dcf-d4fa-4896-bc02-88d10f7fcc83","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"Rigveda 3.1.21 uses the plural ''Vishvamitras'' within the hymn, providing internal textual evidence that the Mandala 3 tradition can speak in family or collective terms rather than only as the voice of one individual.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["5bef2a36-07ca-4a1f-91a1-1454275e2dfa","9227358e-67a7-46f5-a873-bb5582ebb893"],"original_passage_ids":["eee5715c-a576-45d8-89da-c841232e4f80"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Rigveda 3.1.21 uses the plural ''Vishvamitras'' within the hymn, providing internal textual evidence that the Mandala 3 tradition can speak in family or collective terms rather than only as the voice of one individual.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"5bef2a36-07ca-4a1f-91a1-1454275e2dfa","url":"https://vedicheritage.gov.in/samhitas/rigveda/shakala-samhita/mandal-03/","locator":"Rigveda Rigveda 3.1.21, portal lines 453–456","source_authority":"Government of India Vedic Heritage Portal, Rigveda 3.1 Sanskrit text and seer metadata; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"Verse 21 uses the plural Vishvamitras; the claim draws a cautious implication about family/collective usage.","original_source_inspected":true,"material_limitation":"Traditional rishi attribution and hymn text; not independent proof of single-person authorship.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='Rigveda 3.1.21 uses the plural ''Vishvamitras'' within the hymn, providing internal textual evidence that the Mandala 3 tradition can speak in family or collective terms rather than only as the voice of one individual.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='95e35dcf-d4fa-4896-bc02-88d10f7fcc83'::uuid;
