INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('9ea370a1-5ea4-49b3-a42f-a4b4a3fcb985'::uuid,'REVISE AND APPROVE','{"claim_id":"9ea370a1-5ea4-49b3-a42f-a4b4a3fcb985","personality_id":"2853f4ed-98b1-4ef8-9f30-30f85d42edad","personality":"Vishvamitra","original_claim_text":"Rigveda 3.62 attributes verses 1-15 to Gathina Vishvamitra; the Savitr section includes the celebrated 3.62.10 mantra.","original_review_status":"approved","original_approval_origin":"system_test_bulk","original_source_ids":["c2d10c6c-8da2-4f5a-becf-93b160eb267b"],"original_passage_ids":["dbcfbb5a-8120-4b13-9f5a-9d266e46e0d0"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"REVISE AND APPROVE","final_proposed_wording":"The Government of India’s Vedic Heritage Portal gives Gathina Vishvamitra as a traditional rishi attribution for Rigveda 3.62.10, the Savitr mantra.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"c2d10c6c-8da2-4f5a-becf-93b160eb267b","url":"https://vedicheritage.gov.in/hi/samhitas/rigveda/shakala-samhita/rigveda-shakala-samhita-mandal-03-sukta-062/","locator":"Rigveda 3.62 seer/deity metadata, portal line 414; verse 10 line 427","source_authority":"Government of India Vedic Heritage Portal, Rigveda 3.62 Sanskrit text and seer metadata; passage checked 2026-10-19","independence_assessment":"One textual tradition. Independent historical corroboration is neither asserted nor needed for a statement explicitly about that tradition.","original_source_inspected":true,"original_claim_source_linked":true}],"verification_rationale":"Portal metadata identifies Gathina Vishvamitra and Savitar for 10–12; other verses have alternatives. Coordinator narrowed the wording because the source does not assign all verses 1–15 exclusively to him.","original_source_inspected":true,"material_limitation":"Traditional rishi attribution and hymn text; not independent proof of single-person authorship.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
