INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('4d0138bc-475e-41ed-95d2-2c14efa49c3c'::uuid,'APPROVE','{"claim_id":"4d0138bc-475e-41ed-95d2-2c14efa49c3c","personality_id":"6ef206bf-1446-4e3d-94a6-e583f7736e62","personality":"Yajnavalkya","original_claim_text":"The debate closes in Brihadaranyaka 3.9.26 when Yajnavalkya demands that Shakalya identify \"the Person taught in the Upanishads\" on pain of his head falling off; Shakalya cannot, and the text says his head fell off and robbers carried away his bones. This is the narrative’s own claim, not a historical report.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["5d0a41a4-b79b-4182-b6ee-afa099f453da"],"original_passage_ids":["80077056-7c77-4284-bd80-4fb81164e91d"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"The debate closes in Brihadaranyaka 3.9.26 when Yajnavalkya demands that Shakalya identify \"the Person taught in the Upanishads\" on pain of his head falling off; Shakalya cannot, and the text says his head fell off and robbers carried away his bones. This is the narrative’s own claim, not a historical report.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"5d0a41a4-b79b-4182-b6ee-afa099f453da","url":"https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf","locator":"Bṛhadāraṇyaka Upaniṣad 3.9.26, PDF p. 114 (zero-based 113), text lines 3931–3942","source_authority":"Robert Ernest Hume, The Thirteen Principal Upanishads (Oxford University Press, 1921), Liberty Fund PDF; actual translated passage inspected","independence_assessment":"One public-domain scholarly translation of the textual witness; confirms what this edition says, not historical occurrence or independent Sanskrit variants.","original_source_inspected":true}],"verification_rationale":"The text narrates Shakalya’s failed answer, fallen head and stolen bones; this is not independently established history.","original_source_inspected":true,"material_limitation":"Ancient dialogue or doctrine is classified as textual assertion or traditional narrative. The translation alone does not independently establish the narrated event as history.","removal_reason":null,"applied_to_isolated_database":true}'::jsonb);
UPDATE public.claims SET claim_text='The debate closes in Brihadaranyaka 3.9.26 when Yajnavalkya demands that Shakalya identify "the Person taught in the Upanishads" on pain of his head falling off; Shakalya cannot, and the text says his head fell off and robbers carried away his bones. This is the narrative’s own claim, not a historical report.',review_status='approved',approval_origin='corpus_evidence_review',approval_note='Evidence assessed in isolated corpus review; see corpus_verification_audit.decisions',approved_by_label='Corpus evidence review',approved_at=now() WHERE id='4d0138bc-475e-41ed-95d2-2c14efa49c3c'::uuid;
