INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('564b9021-57c5-4f4f-a293-d24ae48f7a15'::uuid,'APPROVE','{"claim_id":"564b9021-57c5-4f4f-a293-d24ae48f7a15","personality_id":"6ef206bf-1446-4e3d-94a6-e583f7736e62","personality":"Yajnavalkya","original_claim_text":"In Brihadaranyaka 4.4.5 Yajnavalkya states the link between action and destiny: as one acts and conducts oneself, so one becomes; and since desire shapes resolve and resolve shapes action, a person obtains what his action (karma) earns.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["5d0a41a4-b79b-4182-b6ee-afa099f453da"],"original_passage_ids":["8c25b061-a4ed-4f7e-b6a8-10947af1a579"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"In Brihadaranyaka 4.4.5 Yajnavalkya states the link between action and destiny: as one acts and conducts oneself, so one becomes; and since desire shapes resolve and resolve shapes action, a person obtains what his action (karma) earns.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"5d0a41a4-b79b-4182-b6ee-afa099f453da","url":"https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf","locator":"Bṛhadāraṇyaka Upaniṣad 4.4.5, PDF p. 127 (zero-based 126), text lines 4376–4386","source_authority":"Robert Ernest Hume, The Thirteen Principal Upanishads (Oxford University Press, 1921), Liberty Fund PDF; actual translated passage inspected","independence_assessment":"One public-domain scholarly translation of the textual witness; confirms what this edition says, not historical occurrence or independent Sanskrit variants.","original_source_inspected":true}],"verification_rationale":"The passage explicitly links conduct, desire, resolve, action and obtained result.","original_source_inspected":true,"material_limitation":"Ancient dialogue or do