INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('827648c4-4036-4669-9813-623d6979029e'::uuid,'APPROVE','{"claim_id":"827648c4-4036-4669-9813-623d6979029e","personality_id":"6ef206bf-1446-4e3d-94a6-e583f7736e62","personality":"Yajnavalkya","original_claim_text":"To Maitreyi, Yajnavalkya compares the great being to a lump of salt dissolved in water, which cannot be picked out yet makes all the water salty: it is a single mass of knowledge, and he adds that \"after death there is no consciousness\".","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["5d0a41a4-b79b-4182-b6ee-afa099f453da"],"original_passage_ids":["abe15184-1aa2-479d-8b13-6461f122ba97"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"To Maitreyi, Yajnavalkya compares the great being to a lump of salt dissolved in water, which cannot be picked out yet makes all the water salty: it is a single mass of knowledge, and he adds that \"after death there is no consciousness\".","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"5d0a41a4-b79b-4182-b6ee-afa099f453da","url":"https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf","locator":"Bṛhadāraṇyaka Upaniṣad 2.4.12–14, PDF p. 90 (zero-based 89), text lines 3181–3201","source_authority":"Robert Ernest Hume, The Thirteen Principal Upanishads (Oxford University Press, 1921), Liberty Fund PDF; actual translated passage inspected","independence_assessment":"One public-domain scholarly translation of the textual witness; confirms what this edition says, not historical occurrence or independent Sanskrit variants.","original_source_inspected":true}],"verification_rationale":"The salt analogy, mass of knowledge and postmortem-consciousness wording appear together. The latter is contextualized by the following duality discussion