INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('0a2a7f1f-c23c-409c-ae84-7cc83bbe1aef'::uuid,'APPROVE','{"claim_id":"0a2a7f1f-c23c-409c-ae84-7cc83bbe1aef","personality_id":"6ef206bf-1446-4e3d-94a6-e583f7736e62","personality":"Yajnavalkya","original_claim_text":"In the earlier telling at Brihadaranyaka 2.4, Maitreyi asks whether the whole earth filled with wealth would make her immortal; Yajnavalkya says wealth gives no hope of immortality, and she asks instead to be taught what he knows.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["5d0a41a4-b79b-4182-b6ee-afa099f453da"],"original_passage_ids":["91ff8426-65d4-403d-a741-162b0d06390c"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"In the earlier telling at Brihadaranyaka 2.4, Maitreyi asks whether the whole earth filled with wealth would make her immortal; Yajnavalkya says wealth gives no hope of immortality, and she asks instead to be taught what he knows.","epistemic_type":"TRADITIONAL_NARRATIVE","evidence_references":[{"source_id":"5d0a41a4-b79b-4182-b6ee-afa099f453da","url":"https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf","locator":"Bṛhadāraṇyaka Upaniṣad 2.4.1–3, PDF p. 88 (zero-based 87), text lines 3117–3124","source_authority":"Robert Ernest Hume, The Thirteen Principal Upanishads (Oxford University Press, 1921), Liberty Fund PDF; actual translated passage inspected","independence_assessment":"One public-domain scholarly translation of the textual witness; confirms what this edition says, not historical occurrence or independent Sanskrit variants.","original_source_inspected":true}],"verification_rationale":"The first Maitreyi conversation directly gives the wealth question, reply and request for instruction.","original_source_inspected":true,"material_limitation":"Ancient di