INSERT INTO corpus_verification_audit.decisions (claim_id, decision, evidence_record) VALUES ('aa0040aa-f111-496f-b616-55ff280c1c11'::uuid,'APPROVE','{"claim_id":"aa0040aa-f111-496f-b616-55ff280c1c11","personality_id":"6ef206bf-1446-4e3d-94a6-e583f7736e62","personality":"Yajnavalkya","original_claim_text":"Brihadaranyaka 4.4.22 links knowledge of the self with renunciation: Brahmins seek the self through Vedic recitation, sacrifice, gifts, austerity and fasting; knowing it one becomes a sage, and those who desire it alone give up the wish for sons, wealth and worlds and wander as mendicants.","original_review_status":"draft","original_approval_origin":"ai_candidate","original_source_ids":["5d0a41a4-b79b-4182-b6ee-afa099f453da"],"original_passage_ids":["70c7c54b-618f-4fbe-9048-a8d5860f3465"],"audit_publication_gate":"DOCUMENTARY_REVIEW_REQUIRED","review_state":"evidence_assessed","decision":"APPROVE","final_proposed_wording":"Brihadaranyaka 4.4.22 links knowledge of the self with renunciation: Brahmins seek the self through Vedic recitation, sacrifice, gifts, austerity and fasting; knowing it one becomes a sage, and those who desire it alone give up the wish for sons, wealth and worlds and wander as mendicants.","epistemic_type":"TEXTUAL_ASSERTION","evidence_references":[{"source_id":"5d0a41a4-b79b-4182-b6ee-afa099f453da","url":"https://oll-resources.s3.us-east-2.amazonaws.com/oll3/store/titles/2058/Hume_1395_EBk_v6.0.pdf","locator":"Bṛhadāraṇyaka Upaniṣad 4.4.22, PDF p. 128 (zero-based 127), text lines 4418–4434","source_authority":"Robert Ernest Hume, The Thirteen Principal Upanishads (Oxford University Press, 1921), Liberty Fund PDF; actual translated passage inspected","independence_assessment":"One public-domain scholarly translation of the textual witness; confirms what this edition says, not historical occurrence or independent Sanskrit variants.","original_source_inspected":true}],"verification_rationale":"The passage lists Vedic recitation, rites and austeri